export const definitions: Record<string, string> = {
  'plaint': 'ഒരു സിവിൽ കേസ് കോടതിയിൽ ആരംഭിക്കാൻ ഒരാൾ ഫയൽ ചെയ്യുന്ന രേഖാമൂലമായ രേഖ. കക്ഷികൾ ആരാണ്, എന്താണ് സംഭവിച്ചത്, കോടതി എന്ത് ഉത്തരവ് നൽകണമെന്നാണ് ആ വ്യക്തി ആവശ്യപ്പെടുന്നത് എന്നിവ ഇതിൽ വിശദീകരിക്കുന്നു.',
  'written-statement': 'പ്ലെയിന്റിൽ ഉന്നയിച്ച ആവശ്യങ്ങൾക്ക് മറുപടിയായി പ്രതി ഒരു സിവിൽ കേസിൽ ഫയൽ ചെയ്യുന്ന ഔപചാരികമായ രേഖാമൂലമായ മറുപടി. ഏതെല്ലാം ആരോപണങ്ങൾ അംഗീകരിക്കുന്നു, ഏതെല്ലാം നിഷേധിക്കുന്നു എന്ന് ഇതിൽ പറയുന്നു, കൂടാതെ പ്രതിയുടെ സ്വന്തം പ്രതിവാദങ്ങളും ഉന്നയിക്കാം.',
  'affidavit': 'ഒരു വ്യക്തി ഒപ്പിട്ട്, നോട്ടറി, ഓത്ത് കമ്മീഷണർ തുടങ്ങിയ അധികാരപ്പെടുത്തിയ ഉദ്യോഗസ്ഥന് മുന്നിൽ സത്യമാണെന്ന് സത്യം ചെയ്ത വസ്തുതകളുടെ രേഖാമൂലമായ പ്രസ്താവന. പല നടപടിക്രമ ആവശ്യങ്ങൾക്കും, വ്യക്തി സ്വയം ഹാജരായി ഇതേ വസ്തുതകൾ ആവർത്തിക്കുന്നതിന് പകരമായി കോടതികൾ ഇത് സ്വീകരിക്കുന്നു.',
  'decree': 'ഒരു സിവിൽ സ്യൂട്ടിൽ കോടതിയുടെ തീരുമാനത്തിന്റെ ഔപചാരികവും അന്തിമവുമായ പ്രകടനം, തർക്കത്തിലുള്ള കാര്യങ്ങളിൽ കക്ഷികളുടെ അവകാശങ്ങൾ നിർണ്ണായകമായി തീർപ്പാക്കുന്നത്. സാധാരണയായി നടപടിക്രമപരമോ ഇടക്കാലമോ ആയ കാര്യങ്ങൾ കൈകാര്യം ചെയ്യുന്ന "ഉത്തരവ്" എന്നതിൽ നിന്ന് ഇത് വ്യത്യസ്തമാണ്.',
  'judicial-order': 'നടപടിക്രമപരമോ ഇടക്കാലമോ ആയ കാര്യങ്ങളിൽ, ഉദാഹരണത്തിന് മാറ്റിവയ്ക്കൽ അനുവദിക്കുകയോ ഒരു രേഖ സ്വീകരിക്കുകയോ പോലുള്ളവയിൽ, കേസിനിടയിൽ കോടതി നൽകുന്ന ഔപചാരികമായ നിർദ്ദേശം. ഡിക്രിയിൽ നിന്ന് വ്യത്യസ്തമായി, ഒരു ഉത്തരവ് കേസിനെയോ അതിലെ ഒരു അവകാശത്തെയോ നിർബന്ധമായും അന്തിമമായി തീർപ്പാക്കണമെന്നില്ല.',
  'ex-parte': 'ഒരു കക്ഷി മാത്രം ഹാജരായിരിക്കുമ്പോൾ നടത്തുന്ന വിചാരണയോ നൽകുന്ന ഉത്തരവോ, സാധാരണയായി നോട്ടീസ് നൽകിയിട്ടും മറുകക്ഷി ഹാജരാകാതിരുന്നതുകൊണ്ട്. ഹാജരാകാതിരുന്ന കക്ഷി ഹിയറിംഗ് നഷ്ടപ്പെട്ടതിന് മതിയായ കാരണം കാണിച്ചാൽ, ഒരു എക്സ് പാർട്ടി ഉത്തരവ് പലപ്പോഴും ചോദ്യം ചെയ്യപ്പെടുകയോ റദ്ദാക്കുകയോ ചെയ്യാം.',
  'limitation-period': 'ഒരാൾ ഒരു കേസ് ഫയൽ ചെയ്യുകയോ ഒരു പ്രത്യേക നിയമപരമായ നടപടി സ്വീകരിക്കുകയോ ചെയ്യേണ്ട സമയപരിധി, കേസ് ചെയ്യാനോ പ്രവർത്തിക്കാനോ ഉള്ള അവകാശം ആദ്യം ഉണ്ടായ തീയതി മുതൽ കണക്കാക്കുന്നത്. വൈകുന്നതിന് സാധുവായ കാരണമില്ലാതെ ഈ കാലയളവിന് ശേഷം ഒരു കേസ് ഫയൽ ചെയ്താൽ, അതിന്റെ മെറിറ്റ് എന്തായാലും കോടതികൾക്ക് അത് കേൾക്കാൻ തന്നെ വിസമ്മതിക്കാം.',
  'cause-of-action': 'ഒരാൾക്ക് മറ്റൊരാൾക്കെതിരെ കേസ് ഫയൽ ചെയ്യാനുള്ള നിയമപരമായ അവകാശം നൽകുന്ന വസ്തുതകളുടെ കൂട്ടം. യഥാർത്ഥമായ ഒരു കോസ് ഓഫ് ആക്ഷൻ നിലവിലുണ്ടെന്നും അത് വ്യക്തമായി പ്രസ്താവിച്ചിട്ടുണ്ടെന്നും ഇല്ലെങ്കിൽ ഒരു കേസ് ഫയൽ ചെയ്യാനാവില്ല, കോടതി അത് പരിഗണിക്കുകയുമില്ല.',
  'jurisdiction': 'വിഷയം, ക്ലെയിമിന്റെ മൂല്യം, കക്ഷികളുടെയോ സ്വത്തിന്റെയോ സ്ഥാനം തുടങ്ങിയ ഘടകങ്ങളെ അടിസ്ഥാനമാക്കി, ഒരു പ്രത്യേക കോടതിക്കോ ട്രിബ്യൂണലിനോ ഒരു കേസ് കേൾക്കാനും തീരുമാനിക്കാനുമുള്ള അധികാരം. അധികാരപരിധി ഇല്ലാത്ത തെറ്റായ ഫോറത്തിൽ ഒരു കേസ് ഫയൽ ചെയ്താൽ, അതിന്റെ മെറിറ്റ് എന്തായാലും അത് തള്ളിപ്പോകുകയോ മറ്റൊരിടത്തേക്ക് മാറ്റുകയോ ചെയ്യാം.',
  'locus-standi': 'ഒരു പ്രത്യേക കേസ് കൊണ്ടുവരാനോ അതിൽ കേൾക്കപ്പെടാനോ ഉള്ള ഒരാളുടെ നിയമപരമായ അവകാശം, അവർ ആ വിഷയത്തിൽ നേരിട്ട് ബാധിക്കപ്പെട്ടിരിക്കുന്നതിനാൽ. ലോക്കസ് സ്റ്റാൻഡി ഇല്ലാത്ത ഒരാളെ, അവരുടെ അടിസ്ഥാന പരാതിക്ക് കഴമ്പുണ്ടെങ്കിൽ പോലും, കോടതിക്ക് കേൾക്കാൻ വിസമ്മതിക്കാം.',
  'adjournment': 'ഒരു കോടതി ഹിയറിംഗ് പിന്നീടൊരു തീയതിയിലേക്ക് നീട്ടിവയ്ക്കൽ, സാധാരണയായി തയ്യാറെടുക്കാൻ കൂടുതൽ സമയം വേണമെന്നോ അഭിഭാഷകൻ ലഭ്യമല്ലെന്നോ പോലുള്ള സാധുവായ കാരണത്താൽ കക്ഷികളിൽ ഒരാളുടെ അപേക്ഷയിൽ അനുവദിക്കുന്നത്.',
  'stay-order': 'ഒരു പ്രത്യേക നടപടി, നടപടിക്രമം, അല്ലെങ്കിൽ ഒരു ലോവർ ഉത്തരവിന്റെ പ്രാബല്യം, കൂടുതൽ നിർദ്ദേശങ്ങൾ ലഭിക്കുന്നതുവരെ താൽക്കാലികമായി നിർത്തുകയോ നിർത്തിവയ്ക്കുകയോ ചെയ്യുന്ന കോടതിയുടെയോ ട്രിബ്യൂണലിന്റെയോ ഉത്തരവ്. ഉദാഹരണത്തിന്, ഒരു ഡിക്രിക്കെതിരെയുള്ള അപ്പീൽ നിലവിലിരിക്കുമ്പോൾ അതിന്റെ നിർവ്വഹണം കോടതിക്ക് സ്റ്റേ ചെയ്യാം.',
  'condonation-of-delay': 'സാധാരണ പരിമിതി കാലയളവ് കഴിഞ്ഞ ശേഷം ഒരു കേസോ അപ്പീലോ ഫയൽ ചെയ്തതിന് ഒരു കക്ഷിക്ക് മാപ്പ് നൽകുന്ന കോടതി ഉത്തരവ്, കക്ഷി കാലതാമസത്തിന് മതിയായതും യഥാർത്ഥവുമായ കാരണം കാണിക്കുമ്പോൾ അനുവദിക്കുന്നത്. ഇതില്ലാതെ, വൈകി ഫയൽ ചെയ്യുന്നത് സാധാരണയായി നേരിട്ട് തള്ളിപ്പോകും.',
  'interlocutory-application': 'പ്രധാന കേസ് ഇപ്പോഴും നിലവിലിരിക്കുമ്പോൾ, കേസിൽ അന്തിമ തീരുമാനമല്ല, ഒരു ഇടക്കാല ഉത്തരവിനോ നിർദ്ദേശത്തിനോ വേണ്ടി കോടതിയിലോ ട്രിബ്യൂണലിലോ നൽകുന്ന അപേക്ഷ. ഇടക്കാല ഇൻജങ്ഷനു വേണ്ടിയോ, ഡിലേ കണ്ടോണേഷനു വേണ്ടിയോ, ഒരു പ്ലീഡിംഗ് ഭേദഗതി ചെയ്യാനുള്ള അനുമതിക്കു വേണ്ടിയോ ഉള്ള അപേക്ഷകൾ സാധാരണ ഉദാഹരണങ്ങളാണ്.',
  'show-cause-notice': 'ഒരു പ്രത്യേക നടപടി തങ്ങൾക്കെതിരെ എന്തുകൊണ്ട് സ്വീകരിക്കരുത് എന്ന് നിശ്ചിത സമയത്തിനകം വിശദീകരിക്കാൻ ഒരു വ്യക്തിയെയോ സ്ഥാപനത്തെയോ ആവശ്യപ്പെടുന്ന ഔപചാരികമായ നോട്ടീസ്. പ്രതികൂലമായ ഒരു തീരുമാനം എടുക്കുന്നതിന് മുൻപ് മറുപടി നൽകാനുള്ള അവസരം ഇത് സ്വീകർത്താവിന് നൽകുന്നു.',
  'interim-order': 'ഒരു കേസ് ഇപ്പോഴും നടന്നുകൊണ്ടിരിക്കുമ്പോൾ കോടതി നൽകുന്ന താൽക്കാലിക ഉത്തരവ്, കേസ് അന്തിമമായി തീർപ്പാക്കുന്നതുവരെ സ്ഥിതി സംരക്ഷിക്കാനോ ഒരു കക്ഷിയുടെ താൽപ്പര്യം സംരക്ഷിക്കാനോ ഉദ്ദേശിച്ചത്. ഇത് തർക്കത്തിന്റെ മെറിറ്റിലുള്ള ഒരു തീരുമാനമല്ല.',
  'summary-suit': 'ചില തരം ക്ലെയിമുകൾക്കായി ഉപയോഗിക്കുന്ന വേഗത്തിലുള്ള സിവിൽ നടപടിക്രമം, സാധാരണയായി ഒടുക്കാത്ത ബില്ലോ രേഖാമൂലമായ കരാറിലെ കടമോ പോലുള്ള ഒരു വ്യക്തവും നിശ്ചിതവുമായ പണത്തുക തിരിച്ചുപിടിക്കുന്നതിന്. പ്രതിയുടെ കേസ് എതിർക്കാനുള്ള സ്വാഭാവികമായ അവകാശം ഇത് പരിമിതപ്പെടുത്തുന്നു, പ്രതിവാദം യഥാർത്ഥമല്ലെന്ന് തോന്നുന്ന കേസുകൾ വേഗത്തിലാക്കുന്നു.',
  'caveat': 'മറുകക്ഷിയിൽ നിന്നുള്ള പ്രതീക്ഷിക്കുന്ന ഒരു അപേക്ഷയിൽ, ഉദാഹരണത്തിന് ഒരു എക്സ് പാർട്ടി ഇൻജങ്ഷനിൽ, ഏതെങ്കിലും ഉത്തരവ് നൽകുന്നതിന് മുൻപ് അറിയിക്കുകയും കേൾക്കുകയും ചെയ്യണമെന്ന് ആവശ്യപ്പെട്ട് കോടതിയിൽ ഫയൽ ചെയ്യുന്ന ഔപചാരികമായ നോട്ടീസ്. ഒരു കേവിയറ്റ് ഫയൽ ചെയ്തുകഴിഞ്ഞാൽ, അത് ഫയൽ ചെയ്തയാളെ ആദ്യം കേൾക്കാനുള്ള അവസരം കോടതി നൽകേണ്ടതുണ്ട്.',
  'plaintiff': 'ഒരു സിവിൽ സ്യൂട്ട് ഫയൽ ചെയ്യുന്ന വ്യക്തി, പ്രതിക്കെതിരെ എന്തെങ്കിലും ആശ്വാസം നൽകാൻ കോടതിയോട് ആവശ്യപ്പെടുന്നത്.',
  'defendant': 'ഒരു സിവിൽ സ്യൂട്ട് ഫയൽ ചെയ്തിരിക്കുന്ന വ്യക്തി, രേഖാമൂലമായ മറുപടി (written statement) ഫയൽ ചെയ്ത് വാദിയുടെ ആവശ്യങ്ങൾക്ക് മറുപടി നൽകാൻ ആവശ്യപ്പെടുന്നയാൾ.',
  'petitioner': 'ഒരു ഹർജി ഫയൽ ചെയ്യുന്ന വ്യക്തി, റിട്ട് ഹർജികൾ, വൈവാഹിക കേസുകൾ, അല്ലെങ്കിൽ കമ്പനി നിയമ നടപടികൾ പോലുള്ള കാര്യങ്ങളിൽ "വാദി" എന്നതിന് പകരം ഉപയോഗിക്കുന്നത്.',
  'respondent': 'ഒരു ഹർജിയോ അപ്പീലോ റിവിഷനോ ഫയൽ ചെയ്തിരിക്കുന്നതിനെതിരെയുള്ള വ്യക്തി, അതിന് മറുപടി നൽകാൻ ആവശ്യപ്പെടുന്നയാൾ, ഒരു സ്യൂട്ടിൽ പ്രതി വഹിക്കുന്ന അതേ പങ്ക് ഈ തരം നടപടികളിൽ വഹിക്കുന്നയാൾ.',
  'appellant': 'ഒരു അപ്പീൽ ഫയൽ ചെയ്യുന്ന വ്യക്തി, ഒരു ലോവർ കോടതിയുടെയോ ട്രിബ്യൂണലിന്റെയോ തീരുമാനത്തെ ചോദ്യം ചെയ്യുന്നയാൾ, ആ തീരുമാനത്തെ ന്യായീകരിക്കുന്ന റെസ്പോണ്ടന്റിൽ നിന്ന് വ്യത്യസ്തമായി.',
  'applicant': 'ഒരു കോടതിയിൽ നിന്നോ ട്രിബ്യൂണലിൽ നിന്നോ ഒരു പ്രത്യേക ഉത്തരവോ നിർദ്ദേശമോ തേടി അപേക്ഷ ഫയൽ ചെയ്യുന്ന വ്യക്തി, ഇന്റർലോക്യൂട്ടറി അപേക്ഷകളിലും NCLT അല്ലെങ്കിൽ ഉപഭോക്തൃ കമ്മീഷൻ പോലുള്ള ട്രിബ്യൂണലുകൾക്ക് മുന്നിലുള്ള നടപടികളിലും ഏറ്റവും സാധാരണയായി ഉപയോഗിക്കുന്ന പദം.',
  'dismissal-for-default': 'ഒരു കക്ഷി, സാധാരണയായി വാദിയോ അപ്പീൽക്കാരനോ, അനുവദിച്ച സമയത്തിനകം ഹാജരാകുന്നതിലോ കോടതി ഫീ അടയ്ക്കുന്നതിലോ രേഖകൾ ഫയൽ ചെയ്യുന്നതിലോ പോലുള്ള ആവശ്യമായ ഒരു നടപടി സ്വീകരിക്കുന്നതിലോ പരാജയപ്പെടുന്നതിനാൽ ഒരു കേസ് അടയ്ക്കുന്ന ഉത്തരവ്. ഇത് കേസിന്റെ മെറിറ്റിലുള്ള ഒരു തീരുമാനമല്ല.',
  'restoration-of-suit': 'ഡിഫോൾട്ടിന് തള്ളിപ്പോയ ഒരു കേസ് പുനരുജ്ജീവിപ്പിക്കാൻ കോടതിയോട് ആവശ്യപ്പെടുന്ന അപേക്ഷ, സാധാരണയായി മുൻപുണ്ടായ ഹാജരാകാതിരിക്കലിനോ പാലിക്കാതിരിക്കലിനോ മതിയായ കാരണം കാണിച്ചുകൊണ്ട്. അനുവദിച്ചാൽ, കേസ് തള്ളിപ്പോയ ഘട്ടത്തിൽ നിന്ന് തുടരും.',
  'transfer-petition': 'ഒരു നിലവിലുള്ള കേസ് ഒരു കോടതിയിൽ നിന്നോ ട്രിബ്യൂണലിൽ നിന്നോ മറ്റൊന്നിലേക്ക് മാറ്റാൻ ഉയർന്ന കോടതിയോട് ആവശ്യപ്പെടുന്ന അപേക്ഷ, സാധാരണയായി കക്ഷികളുടെ സൗകര്യം, ന്യായമായ വിചാരണ ഉറപ്പാക്കൽ, അല്ലെങ്കിൽ മറ്റൊരു കോടതിയിൽ ഇതിനോട് ബന്ധപ്പെട്ട ഒരു കേസ് ഇതിനകം ഉള്ളത് തുടങ്ങിയ കാരണങ്ങളിൽ.',
  'pecuniary-jurisdiction': 'ഉൾപ്പെട്ടിരിക്കുന്ന ക്ലെയിമിന്റെ പണമൂല്യത്തെ പ്രത്യേകമായി അടിസ്ഥാനമാക്കി ഒരു കേസ് കേൾക്കാനുള്ള കോടതിയുടെ അധികാരം. കോടതികൾക്കും ട്രിബ്യൂണലുകൾക്കും സാധാരണയായി മൂല്യ പരിധികൾ നിശ്ചയിച്ചിട്ടുണ്ട്, അതിനാൽ നിശ്ചയിച്ച പരിധിക്ക് മുകളിലോ താഴെയോ ഉള്ള ഒരു ക്ലെയിം വേറൊരു ഫോറത്തിൽ ഫയൽ ചെയ്യേണ്ടിവരും.',
  'substituted-service': 'ഒരു കക്ഷിക്ക് നോട്ടീസോ സമൻസോ നേരിട്ടോ വ്യക്തിപരമായോ കൈമാറാൻ കഴിയാതിരുന്നപ്പോൾ ഉപയോഗിക്കുന്ന ഒരു ബദൽ രീതി, ഉദാഹരണത്തിന് ഒരു പത്രത്തിൽ നോട്ടീസ് പ്രസിദ്ധീകരിച്ചോ കക്ഷിയുടെ അവസാനം അറിയപ്പെട്ട വിലാസത്തിൽ പതിച്ചോ.',
  'court-fee': 'ഒരു പ്ലെയിന്റോ ഹർജിയോ അപ്പീലോ ഫയൽ ചെയ്യുന്നതിന് മുൻപ്, സാധാരണയായി സ്റ്റാമ്പുകൾ വഴിയോ ഓൺലൈൻ പേയ്മെന്റ് വഴിയോ, സർക്കാരിന് നൽകുന്ന ഫീസ്. ചില തരം ഫയലിംഗുകൾക്ക് പരിധി വിധേയമായി, കേസിൽ ക്ലെയിം ചെയ്ത തുകയുടെയോ മൂല്യത്തിന്റെയോ ഒരു ശതമാനമായി ഇത് സാധാരണയായി കണക്കാക്കുന്നു.',
  'next-friend': 'പ്രായപൂർത്തിയാകാത്ത ഒരു വാദിക്കുവേണ്ടി സിവിൽ സ്യൂട്ട് ഫയൽ ചെയ്യുകയും നടത്തുകയും ചെയ്യുന്ന ഉത്തരവാദിത്തമുള്ള മുതിർന്ന വ്യക്തി, സാധാരണയായി ഒരു രക്ഷിതാവോ അടുത്ത ബന്ധുവോ, കാരണം പ്രായപൂർത്തിയാകാത്ത ഒരാൾക്ക് സ്വന്തം പേരിൽ കേസ് ഫയൽ ചെയ്യാനാവില്ല.',

  'petition': 'കോടതിയോ ട്രിബ്യൂണലോ ഒരു പ്രത്യേക നടപടി സ്വീകരിക്കണമെന്ന് ആവശ്യപ്പെടുന്ന ഔപചാരികമായ രേഖാമൂലമായ അപേക്ഷ, റിട്ട്, കമ്പനി നിയമ കേസുകൾ, വൈവാഹിക കേസുകൾ, അല്ലെങ്കിൽ ചില ഫോറങ്ങളിലേക്കുള്ള അപ്പീലുകൾ പോലുള്ള കാര്യങ്ങളിൽ ഒരു പ്ലെയിന്റിന് പകരം ഉപയോഗിക്കുന്നത്. ഫോറവും കേസിന്റെ തരവും അനുസരിച്ച് ഇതിന്റെ ഘടനയും ആവശ്യകതകളും വ്യത്യാസപ്പെടുന്നു.',
  'memorandum-of-appeal': 'ഒരു അപ്പീൽ ആരംഭിക്കാൻ ഫയൽ ചെയ്യുന്ന ഔപചാരികമായ രേഖ, ലോവർ കോടതിയുടെയോ ട്രിബ്യൂണലിന്റെയോ തീരുമാനത്തെ അപ്പീൽക്കാരൻ ചോദ്യം ചെയ്യുന്ന കാരണങ്ങൾ വിശദീകരിക്കുന്നത്. സാധാരണയായി മുൻപത്തെ തീരുമാനത്തിൽ എന്താണ് തെറ്റെന്ന് വിശദീകരിക്കുന്ന ഓരോ കാരണവും പ്രത്യേകം നമ്പർ നൽകിയ പോയിന്റായി പട്ടികപ്പെടുത്തുന്നു.',
  'vakalatnama': 'ഒരു പ്രത്യേക അഭിഭാഷകനെയോ ലോ ഫേമിനെയോ കോടതിയിൽ ഒരു കേസിൽ തന്നെ പ്രതിനിധീകരിക്കാൻ അധികാരപ്പെടുത്തി ക്ലയന്റ് ഒപ്പിടുന്ന രേഖ. അഭിഭാഷകന് ഔപചാരികമായി ഹാജരാകുന്നതിനും ക്ലയന്റിനു വേണ്ടി പ്രവർത്തിക്കുന്നതിനും മുൻപ് ഇത് ഫയൽ ചെയ്തിരിക്കണം.',
  'index-of-documents': 'ഒരു കോടതി ഫയലിംഗിന്റെ തുടക്കത്തിൽ വയ്ക്കുന്ന ലിസ്റ്റ്, അതിൽ ഉൾപ്പെടുന്ന എല്ലാ രേഖകളുടെയും സംഗ്രഹം, സാധാരണയായി പേജ് നമ്പറുകളോടെ. കോടതിക്കും മറുകക്ഷിക്കും ഫയലിംഗിലെ ഏത് പ്രത്യേക രേഖയും വേഗത്തിൽ കണ്ടെത്താൻ ഇത് സഹായിക്കുന്നു.',
  'annexure': 'ഒരു പ്ലീഡിംഗിലോ ഹർജിയിലോ അതിൽ പ്രസ്താവിച്ച വസ്തുതകളെ പിന്തുണയ്ക്കാൻ ചേർക്കുന്ന ഒരു സഹായക രേഖ, ഉദാഹരണത്തിന് ഒരു കരാറോ രസീതോ കത്തോ. അനെക്‌ഷറുകൾ സാധാരണയായി അക്ഷരങ്ങളോ നമ്പറുകളോ നൽകി ലേബൽ ചെയ്യുന്നു, പ്രധാന രേഖയിൽ ആ ലേബൽ ഉപയോഗിച്ച് പരാമർശിക്കുന്നു.',
  'verification-clause': 'ഒരു പ്ലീഡിംഗിന്റെ അവസാനത്തെ ഒരു ചെറിയ ഒപ്പിട്ട പ്രസ്താവന, ഫയൽ ചെയ്യുന്ന വ്യക്തി അതിലെ ഉള്ളടക്കം തന്റെ അറിവ് പ്രകാരമോ, സത്യമെന്ന് വിശ്വസിക്കുന്ന വിവരം പ്രകാരമോ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്നത്. രേഖയിൽ പ്രസ്താവിച്ച കാര്യങ്ങൾക്ക് ഫയൽ ചെയ്തയാളെ വ്യക്തിപരമായി ഉത്തരവാദിയാക്കാനാണ് ഇത് ഉദ്ദേശിക്കുന്നത്.',
  'cause-title': 'ഒരു കോടതി രേഖയുടെ മുകളിലുള്ള തലക്കെട്ട്, കോടതിയുടെ പേരും കേസ് നമ്പറും കക്ഷികളെയും പേരെടുത്ത് പറയുന്നത്, സാധാരണയായി "വാദി വേഴ്സസ് പ്രതി" എന്ന രീതിയിൽ എഴുതുന്നത്. ഇത് ഏത് കേസിലാണ് ഈ രേഖ ഉൾപ്പെടുന്നതെന്ന് കൃത്യമായി തിരിച്ചറിയുന്നു.',
  'prayer-clause': 'ഒരു പ്ലീഡിംഗിന്റെയോ ഹർജിയുടെയോ ഭാഗം, സാധാരണയായി അവസാനം, കോടതിയോട് നിർദ്ദിഷ്ടമായ ഏത് ആശ്വാസമോ ഉത്തരവോ ആവശ്യപ്പെടുന്നുവെന്ന് വ്യക്തമായി പ്രസ്താവിക്കുന്നത്. പ്രെയർ ക്ലോസിൽ പ്രത്യേകമായി ആവശ്യപ്പെടാത്ത ആശ്വാസം കോടതികൾ സാധാരണയായി നൽകില്ല.',
  'schedule-to-document': 'ഒരു ഡീഡോ പ്ലെയിന്റോ പോലുള്ള ഒരു നിയമ രേഖയുടെ അവസാനത്തെ ഒരു ഭാഗം, രേഖയിൽ മറ്റൊരിടത്ത് പരാമർശിച്ച വിശദമായ വിവരം നൽകുന്നത്, ഉദാഹരണത്തിന് ഒരു സ്വത്തിന്റെ കൃത്യമായ വിവരണവും അതിരുകളും. ഈ വിശദാംശം ഒരു പ്രത്യേക ഷെഡ്യൂളിൽ സൂക്ഷിക്കുന്നത് രേഖയുടെ പ്രധാന ഭാഗം വായിക്കാൻ എളുപ്പമാക്കുന്നു.',
  'rejoinder': 'ഒരു കേസ് ആരംഭിച്ച കക്ഷി ഫയൽ ചെയ്യുന്ന രേഖാമൂലമായ മറുപടി, മറുകക്ഷി ഫയൽ ചെയ്ത രേഖാമൂലമായ മറുപടിക്കോ റിപ്ലൈയ്ക്കോ മറുപടിയായി. ഉയർത്തിയ പുതിയ പോയിന്റുകൾക്കോ പ്രതിവാദങ്ങൾക്കോ യഥാർത്ഥ കക്ഷിക്ക് മറുപടി നൽകാൻ ഇത് അനുവദിക്കുന്നു.',
  'counter-affidavit': 'മറുകക്ഷി ഫയൽ ചെയ്ത സത്യവാങ്മൂലത്തിനോ അപേക്ഷയ്ക്കോ മറുപടിയായി ഒരു കക്ഷി ഫയൽ ചെയ്യുന്ന സത്യവാങ്മൂലം, അതിൽ പ്രസ്താവിച്ച വസ്തുതകളെയും ആവശ്യങ്ങളെയും എതിർത്തോ അവയ്ക്ക് മറുപടി നൽകിയോ.',
  'legal-notice': 'മറ്റൊരു വ്യക്തിക്കോ സ്ഥാപനത്തിനോ, സാധാരണയായി ഒരു അഭിഭാഷകൻ വഴി, അയയ്ക്കുന്ന ഔപചാരികമായ രേഖാമൂലമായ ആശയവിനിമയം, ഒരു പരാതി അറിയിക്കുകയും പ്രസ്താവിച്ച സമയത്തിനകം അത് പരിഹരിച്ചില്ലെങ്കിൽ നിയമനടപടി മുന്നറിയിപ്പ് നൽകുകയും ചെയ്യുന്നത്. ചില തരം കേസുകൾ ഫയൽ ചെയ്യുന്നതിന് മുൻപ് ഇത് അയയ്ക്കുന്നത് പലപ്പോഴും ആവശ്യമോ ഉപദേശിക്കപ്പെടുന്നതോ ആയ ഒരു ഘട്ടമാണ്.',
  'written-submissions': 'ഒരു കക്ഷി കോടതി പരിഗണിക്കണമെന്ന് ആഗ്രഹിക്കുന്ന വാദങ്ങളും നിയമപരമായ പോയിന്റുകളും രേഖാമൂലം അവതരിപ്പിക്കുന്ന രേഖ, പലപ്പോഴും വാചികമായ വാദങ്ങൾ കഴിഞ്ഞശേഷമോ ദൈർഘ്യമേറിയ വാചിക ഹിയറിംഗിന് പകരമായോ ഫയൽ ചെയ്യുന്നത്. അന്തിമ തീരുമാനം തയ്യാറാക്കുമ്പോൾ കോടതികൾ പലപ്പോഴും രേഖാമൂലമായ സബ്മിഷനുകൾ തിരിച്ചു പരിശോധിക്കും.',
  'certified-copy': 'ഒരു കോടതി ഉത്തരവിന്റെയോ വിധിയുടെയോ രേഖയുടെയോ ഔദ്യോഗികമായ പകർപ്പ്, അത് റെക്കോർഡിലുള്ള ഒറിജിനലിന്റെ ശരിയായതും കൃത്യവുമായ പകർപ്പാണെന്ന് സ്ഥിരീകരിക്കാൻ കോടതിയുടെ രജിസ്ട്രി സ്റ്റാമ്പ് ചെയ്ത് ഒപ്പിട്ടത്. ഒരു അപ്പീൽ ഫയൽ ചെയ്യാനോ മറ്റെവിടെയെങ്കിലും ഒരു രേഖയുടെ ഉള്ളടക്കം തെളിയിക്കാനോ സർട്ടിഫൈഡ് കോപ്പികൾ പലപ്പോഴും ആവശ്യമാണ്.',
  'memorandum-of-parties': 'ഒരു ഹർജിയുടെയോ അപ്പീലിന്റെയോ തുടക്കത്തെ ലിസ്റ്റ്, കേസിലെ എല്ലാ കക്ഷികളുടെയും പേരും വിലാസവും പട്ടികപ്പെടുത്തുന്നത്, ഹ്രസ്വമായ കോസ് ടൈറ്റിലിൽ നിന്ന് വ്യത്യസ്തമായി. ഹൈക്കോടതികൾക്കും സുപ്രീം കോടതിക്കും മുൻപാകെ ഉള്ളത് പോലുള്ള, പൂർണ്ണമായ കക്ഷി വിശദാംശങ്ങൾ വേറെ നൽകണമെന്ന് ആവശ്യപ്പെടുന്ന ഫയലിംഗുകളിൽ ഇത് ഉപയോഗിക്കുന്നു.',
  'synopsis-and-list-of-dates': 'കേസ് പശ്ചാത്തലത്തിന്റെ ഒരു ഹ്രസ്വ സംഗ്രഹം, പ്രധാന സംഭവങ്ങളുടെയും അവയുടെ തീയതികളുടെയും കാലക്രമ പട്ടികയോടൊപ്പം, ഹൈക്കോടതികളിലും സുപ്രീം കോടതിയിലും ഹർജികളുടെ തുടക്കത്തിൽ ഫയൽ ചെയ്യുന്നത്. പൂർണ്ണമായ ഹർജി വായിക്കുന്നതിന് മുൻപ് ജഡ്ജിക്ക് കേസ് ചരിത്രം വേഗത്തിൽ മനസ്സിലാക്കാൻ ഇത് സഹായിക്കുന്നു.',
  'written-version': 'ഉപഭോക്തൃ കമ്മീഷന് മുന്നിലുള്ള ഒരു കേസിൽ മറുകക്ഷി ഫയൽ ചെയ്യുന്ന ഔപചാരികമായ രേഖാമൂലമായ മറുപടി, പരാതിയിൽ ഉന്നയിച്ച ആരോപണങ്ങൾക്ക് മറുപടി നൽകുന്നത്. ഒരു സാധാരണ സിവിൽ സ്യൂട്ടിൽ രേഖാമൂലമായ മറുപടി (written statement) നിർവ്വഹിക്കുന്ന അതേ ധർമ്മം ഇത് അവിടെ നിർവ്വഹിക്കുന്നു.',
  'memorandum-of-appearance': 'NCLT പോലുള്ള ചില ട്രിബ്യൂണലുകൾക്ക് മുൻപ് ഫയൽ ചെയ്യുന്ന രേഖ, അതിലൂടെ ഒരു കക്ഷിയുടെ അധികാരപ്പെടുത്തിയ പ്രതിനിധി ഒരു കേസിൽ ഔപചാരികമായി ഹാജരാകുന്നു, കോടതിയിൽ ഫയൽ ചെയ്യുന്ന വകാലത്‌നാമയുടെ അതേ ധർമ്മം നിർവ്വഹിക്കുന്നത്.',
  'affidavit-of-service': 'ഒരു മറുകക്ഷിക്ക് നോട്ടീസോ സമൻസോ മറ്റ് രേഖയോ സർവ് ചെയ്ത വ്യക്തി ഫയൽ ചെയ്യുന്ന സത്യവാങ്മൂലം, അത് എപ്പോൾ, എങ്ങനെ, ആർക്കാണ് സർവ് ചെയ്തതെന്ന് സ്ഥിരീകരിക്കുന്നത്. ശരിയായ സർവീസ് നടന്നിട്ടുണ്ടെന്ന് ഉറപ്പാക്കാൻ കോടതികൾ ഇതിനെ ആശ്രയിക്കുന്നു.',
  'list-of-witnesses': 'തെളിവെടുപ്പ് ആരംഭിക്കുന്നതിന് മുൻപ് ഒരു കക്ഷി ഫയൽ ചെയ്യുന്ന ലിസ്റ്റ്, തങ്ങളുടെ കേസ് തെളിയിക്കാൻ ഹാജരാക്കാൻ ഉദ്ദേശിക്കുന്ന സാക്ഷികളുടെ പേര് നൽകുന്നത്. ആരെയൊക്കെ വിസ്തരിക്കും എന്ന് മുൻകൂട്ടി കോടതിക്കും മറുകക്ഷിക്കും ഇത് അറിയിക്കുന്നു.',
  'paper-book': 'ഒരു കേസിലെ എല്ലാ പ്രസക്തമായ പ്ലീഡിംഗുകളും രേഖകളും ഉത്തരവുകളും സമാഹരിച്ച ഒരു സെറ്റ്, ഒന്നിച്ച് ബൈൻഡ് ചെയ്ത് ഇൻഡെക്സ് ചെയ്തത്, പ്രധാനമായും ഉയർന്ന കോടതികൾക്കും ട്രിബ്യൂണലുകൾക്കും മുൻപാകെയുള്ള അപ്പീലുകൾക്കും ഹിയറിംഗുകൾക്കും ഉപയോഗിക്കാൻ തയ്യാറാക്കിയത്.',
  'supplementary-affidavit': 'ഒരു കക്ഷി തങ്ങളുടെ യഥാർത്ഥ സത്യവാങ്മൂലത്തിന് ശേഷം ഫയൽ ചെയ്യുന്ന അധിക സത്യവാങ്മൂലം, മുൻപ് ഉൾപ്പെടാത്ത പുതിയ വസ്തുതകളോ രേഖകളോ സംഭവവികാസങ്ങളോ കോടതിയുടെ മുന്നിൽ വയ്ക്കാൻ, പൂർണ്ണമായി പുതിയൊരു അപേക്ഷ ഫയൽ ചെയ്യുന്നതിന് പകരമായി.',
  'amendment-of-pleadings': 'ഒരു കക്ഷിക്ക് തങ്ങളുടെ പ്ലെയിന്റിലോ രേഖാമൂലമായ മറുപടിയിലോ, അത് ഇതിനകം ഫയൽ ചെയ്ത ശേഷം, ഒരു വസ്തുതയോ ഒരു ആശ്വാസമോ ചേർക്കുന്നത് പോലുള്ള ഒരു തിരുത്തലോ കൂട്ടിച്ചേർക്കലോ നടത്താൻ അനുവദിക്കുന്ന കോടതിയുടെ അനുമതി. ഇത് കേസിന്റെ സ്വഭാവത്തെ മൗലികമായി മാറ്റുന്നില്ലെങ്കിൽ കോടതികൾ സാധാരണയായി ഇത് അനുവദിക്കും.',
  'undertaking': 'കോടതിക്ക് നൽകുന്ന ഔപചാരികമായ വാഗ്ദാനം, ഒന്നുകിൽ വാചികമായി നൽകി ഉത്തരവിൽ രേഖപ്പെടുത്തിയോ, അല്ലെങ്കിൽ ഒരു സത്യവാങ്മൂലം വഴിയോ, ഒരു കക്ഷി ഒരു പ്രത്യേക കാര്യം ചെയ്യുമെന്നോ ചെയ്യില്ലെന്നോ. കോടതിക്ക് നൽകിയ ഒരു ഉടമ്പടി ലംഘിക്കുന്നത് തന്നെ കോടതിയലക്ഷ്യമായി കണക്കാക്കാം.',
  'notice-of-motion': 'പ്രധാനമായും ചില ഹൈക്കോടതികളുടെ ഒറിജിനൽ സിവിൽ അധികാരപരിധിയിൽ ഫയൽ ചെയ്യുന്ന ഔപചാരികമായ നോട്ടീസ്, ഒരു നിശ്ചിത തീയതിയിൽ ഇടക്കാല ആശ്വാസത്തിനുള്ള അപേക്ഷ കോടതിയിൽ നീക്കുമെന്ന് മറുകക്ഷിയെ അറിയിക്കുന്നത്.',
  'reply-to-legal-notice': 'ഒരു ലീഗൽ നോട്ടീസ് സ്വീകരിച്ച വ്യക്തി, സ്വന്തം അഭിഭാഷകൻ വഴി, ഒരു കേസ് ഫയൽ ചെയ്യുന്നതിന് മുൻപ് അയയ്ക്കുന്ന രേഖാമൂലമായ മറുപടി, അതിൽ ഉന്നയിച്ച ആവശ്യങ്ങൾ അംഗീകരിച്ചോ നിഷേധിച്ചോ വിശദീകരിച്ചോ.',
  'compilation-of-judgments': 'ഒരു കേസിൽ ഉന്നയിച്ച നിയമപരമായ വാദങ്ങളെ പിന്തുണയ്ക്കാൻ ഒരു കക്ഷി ആശ്രയിച്ച് കോടതിയിൽ ഫയൽ ചെയ്യുന്ന, മുൻപ് തീരുമാനിച്ച വിധികളുടെ ബൈൻഡ് ചെയ്ത ഒരു സെറ്റ്.',

  'examination-in-chief': 'ഒരു സാക്ഷിയെ ആദ്യമായി ചോദ്യം ചെയ്യുന്ന ഘട്ടം, ആ സാക്ഷിയെ സാക്ഷ്യപ്പെടുത്താൻ വിളിച്ച കക്ഷിയുടെ അഭിഭാഷകൻ നടത്തുന്നത്. ആ കക്ഷിയുടെ കേസിനെ പിന്തുണയ്ക്കുന്ന വസ്തുതകൾ പുറത്തുകൊണ്ടുവരുകയാണ് ഇതിന്റെ ലക്ഷ്യം.',
  'cross-examination': 'എക്സാമിനേഷൻ-ഇൻ-ചീഫ് കഴിഞ്ഞശേഷം, മറുകക്ഷിയുടെ അഭിഭാഷകൻ ഒരു സാക്ഷിയെ ചോദ്യം ചെയ്യുന്നത്. സാക്ഷിയുടെ വിവരണം പരിശോധിക്കുക, ബലഹീനതകളോ വൈരുദ്ധ്യങ്ങളോ തുറന്നുകാട്ടുക, അവരുടെ വിശ്വാസ്യതയെ ചോദ്യം ചെയ്യുക എന്നിവയാണ് ഇതിന്റെ ലക്ഷ്യം.',
  're-examination': 'ക്രോസ്-എക്സാമിനേഷന് ശേഷം, ആദ്യം ആ സാക്ഷിയെ വിളിച്ച കക്ഷി നടത്തുന്ന ഒരു കൂടുതൽ ചോദ്യം ചെയ്യൽ ഘട്ടം, ക്രോസ്-എക്സാമിനേഷനിൽ ഉയർന്നുവന്ന പോയിന്റുകൾ വ്യക്തമാക്കുന്നതിന് മാത്രം പരിമിതപ്പെടുത്തിയത്.',
  'hearsay': 'ഒരു സാക്ഷി കോടതിയിൽ, താൻ നേരിട്ട് കണ്ടതോ അനുഭവിച്ചതോ ആയ കാര്യത്തിന് പകരം, മറ്റൊരാൾ തന്നോട് പറഞ്ഞ ഒരു കാര്യത്തെക്കുറിച്ച് നടത്തുന്ന പ്രസ്താവന. ഹിയർസേ സാധാരണയായി വിശ്വസനീയമായ തെളിവായി കണക്കാക്കില്ല, എങ്കിലും അംഗീകരിക്കാവുന്ന ചില അംഗീകൃത ഇളവുകൾ നിലവിലുണ്ട്.',
  'burden-of-proof': 'ഒരു കക്ഷി അവകാശപ്പെടുന്ന വസ്തുതകൾ തെളിയിക്കാനുള്ള മൊത്തത്തിലുള്ള നിയമപരമായ ബാധ്യത, അതിനാൽ ഒരു തെളിവും ഹാജരാക്കിയില്ലെങ്കിൽ ആ പോയിന്റിൽ അവർ തോൽക്കും. മിക്ക സിവിൽ, ക്രിമിനൽ കേസുകളിലും, ഈ ഉത്തരവാദിത്തം തുടക്കത്തിൽ തന്നെ നിയമം നിശ്ചയിക്കുന്നതാണ്, സാധാരണയായി മറുകക്ഷിയിലേക്ക് മാറുന്നില്ല.',
  'deposition': 'ഒരു സാക്ഷിയുടെ സത്യം ചെയ്ത സാക്ഷ്യത്തിന്റെ ഔപചാരികമായ രേഖ, എക്സാമിനേഷൻ-ഇൻ-ചീഫ്, ക്രോസ്-എക്സാമിനേഷൻ, റീ-എക്സാമിനേഷൻ എന്നിവയുടെ ഗതിയിൽ രേഖപ്പെടുത്തുന്നത്. കേസ് തീരുമാനിക്കുമ്പോൾ കോടതി ആശ്രയിക്കുന്ന ഔദ്യോഗിക കേസ് റെക്കോർഡിന്റെ ഭാഗമായി ഇത് മാറുന്നു.',
  'exhibit-evidence': 'ഒരു കേസിനിടയിൽ ഔപചാരികമായി തെളിവായി സ്വീകരിച്ച്, പിന്നീട് തിരിച്ചറിയാൻ കഴിയുന്ന വിധം ഒരു റഫറൻസ് നമ്പറോ അക്ഷരമോ നൽകി മാർക്ക് ചെയ്ത ഒരു രേഖയോ വസ്തുവോ. ഒരിക്കൽ എക്സിബിറ്റായി മാർക്ക് ചെയ്താൽ, കോടതിക്കും ഇരുകക്ഷികൾക്കും കേസിന്റെ ബാക്കി ഭാഗത്തും ആ മാർക്കിംഗ് ഉപയോഗിച്ച് അതിനെ പരാമർശിക്കാം.',
  'documentary-evidence': 'കരാറുകൾ, കത്തുകൾ, രസീതുകൾ, അല്ലെങ്കിൽ ഇലക്ട്രോണിക് റെക്കോർഡുകൾ പോലുള്ള രേഖാമൂലമായോ രേഖപ്പെടുത്തിയതോ ആയ രൂപത്തിലുള്ള തെളിവ്, ഒരു കേസിലെ ഒരു വസ്തുത തെളിയിക്കാൻ ഹാജരാക്കുന്നത്. ഒരു സാക്ഷി സ്വന്തം നിലയിൽ നൽകുന്ന സാക്ഷ്യമായ വാചികമായ തെളിവിൽ നിന്ന് ഇതിനെ വേർതിരിക്കുന്നു.',
  'oral-evidence': 'ഒരു സാക്ഷി കോടതിക്ക് മുന്നിൽ നേരിട്ട് സംസാരിച്ച് നൽകുന്ന തെളിവ്, സാധാരണയായി സത്യപ്രതിജ്ഞയ്ക്ക് ശേഷം, രേഖാമൂലമായോ രേഖപ്പെടുത്തിയ രൂപത്തിലോ ഉള്ള ഡോക്യുമെന്ററി തെളിവിന് വിപരീതമായി. വാചികമായ തെളിവ് സാധാരണയായി എക്സാമിനേഷൻ-ഇൻ-ചീഫ്, ക്രോസ്-എക്സാമിനേഷൻ, റീ-എക്സാമിനേഷൻ എന്നിവയിലൂടെ എടുത്ത് രേഖപ്പെടുത്തുന്നു.',
  'admission-evidence': 'വാചികമായോ രേഖാമൂലമായോ പെരുമാറ്റത്തിലൂടെയോ ഒരു കക്ഷി കേസിൽ തന്റെ സ്വന്തം താൽപ്പര്യത്തിന് വിരുദ്ധമായ ഒരു വസ്തുത അംഗീകരിക്കുന്ന പ്രസ്താവന. ഒരാൾ തന്റെ സ്വന്തം കേസിന് ദോഷം ചെയ്യുന്ന സത്യമല്ലാത്ത ഒന്ന് അംഗീകരിക്കാൻ സാധ്യതയില്ലാത്തതിനാൽ, കോടതികൾ അഡ്മിഷനുകളെ ശക്തമായ തെളിവായി കണക്കാക്കുന്നു.',
  'onus-of-proof': 'വിചാരണയുടെ ഒരു പ്രത്യേക ഘട്ടത്തിൽ ഒരു പ്രത്യേക വിഷയത്തിൽ തെളിവ് ഹാജരാക്കാനുള്ള ബാധ്യത, മൊത്തത്തിലുള്ള ബർഡൻ ഓഫ് പ്രൂഫിൽ നിന്ന് വ്യത്യസ്തമായി. ബർഡൻ ഓഫ് പ്രൂഫിൽ നിന്ന് വ്യത്യസ്തമായി, ഓരോ കക്ഷിയും ഒരു പോയിന്റിൽ തെളിവ് ഹാജരാക്കുകയോ ഹാജരാക്കാതിരിക്കുകയോ ചെയ്യുന്നതിനനുസരിച്ച് ഓണസ് മുന്നോട്ടും പിന്നോട്ടും മാറാം.',
  'hostile-witness': 'സാക്ഷ്യം നൽകുമ്പോൾ, താൻ വിളിച്ച കക്ഷിക്ക് മുൻപ് നൽകിയ പ്രസ്താവനയ്ക്ക് വിരുദ്ധമായി സംസാരിക്കുന്ന, അല്ലെങ്കിൽ ആ കക്ഷിയുടെ കേസിനെ പിന്തുണയ്ക്കാൻ മനസ്സില്ലാത്തതായി തോന്നുന്ന സാക്ഷി. ഒരു സാക്ഷിയെ ഹോസ്റ്റൈൽ ആയി കോടതി പ്രഖ്യാപിച്ചുകഴിഞ്ഞാൽ, അവരെ വിളിച്ച കക്ഷിക്ക് ഒരു ക്രോസ്-എക്സാമിനേഷന് സമാനമായി കൂടുതൽ നേരിട്ട് ചോദ്യം ചെയ്യാൻ അനുവാദം ലഭിച്ചേക്കാം.',
  'expert-opinion': 'ഒരു ഡോക്ടറോ ഫോറൻസിക് പരിശോധകനോ കൈയെഴുത്ത് വിദഗ്ധനോ പോലുള്ള, ഒരു പ്രത്യേക മേഖലയിൽ പ്രത്യേക വൈദഗ്ധ്യമോ അറിവോ ഉള്ള വ്യക്തിയുടെ അഭിപ്രായം, കോടതിക്ക് സ്വന്തമായി വിലയിരുത്താൻ കഴിയാത്ത സാങ്കേതിക ചോദ്യത്തിൽ തെളിവായി അവതരിപ്പിക്കുന്നത്. ഒരു വിദഗ്ധന്റെ അഭിപ്രായം അംഗീകരിക്കാൻ ബാധ്യതയില്ലാതെ, ബാക്കിയുള്ള തെളിവുകളോടൊപ്പം കോടതി അതിന് തൂക്കം നൽകുന്നു.',
  'circumstantial-evidence': 'ഒരു വസ്തുത നേരിട്ട് തെളിയിക്കാത്ത, പക്ഷേ ബന്ധപ്പെട്ട ഒരു കൂട്ടം സാഹചര്യങ്ങളിൽ നിന്ന് ന്യായമായി അനുമാനിക്കാൻ കോടതിയെ അനുവദിക്കുന്ന തെളിവ്. സാഹചര്യത്തെളിവ് മാത്രം അടിസ്ഥാനമാക്കി കോടതികൾക്ക് ശിക്ഷിക്കാനോ ഒരു കേസ് തീരുമാനിക്കാനോ കഴിയും, പക്ഷേ സാധാരണയായി സാഹചര്യങ്ങൾ ഒന്നിച്ചെടുത്താൽ ഒരേയൊരു വിശദീകരണത്തിലേക്ക് നിർണ്ണായകമായി വിരൽ ചൂണ്ടുമ്പോൾ മാത്രം.',
  'corroboration': 'ഇതിനകം നൽകിയ മറ്റൊരു തെളിവിനെ പിന്തുണയ്ക്കുകയും സ്ഥിരീകരിക്കുകയും ചെയ്യുന്ന സ്വതന്ത്രമായ തെളിവ്, ഉദാഹരണത്തിന് ആദ്യ സാക്ഷിയുടെ വിവരണത്തെ പിന്തുണയ്ക്കുന്ന രണ്ടാമത്തെ സാക്ഷി. ചില തരം തെളിവുകൾ, അവ കോറോബറേറ്റ് ചെയ്യപ്പെടുമ്പോൾ കൂടുതൽ വിശ്വസനീയമായി കണക്കാക്കുന്നു, ചില സാഹചര്യങ്ങളിൽ പ്രയോഗത്തിൽ ആവശ്യമായും കണക്കാക്കുന്നു.',
  'presumption': 'ചില വസ്തുതകളിൽ നിന്ന് കോടതി അനുമാനിക്കാൻ നിയമം അനുവദിക്കുന്നതോ ആവശ്യപ്പെടുന്നതോ ആയ ഒരു നിഗമനം, വിരുദ്ധമായ തെളിവ് കൊണ്ട് നിരാകരിക്കപ്പെടാത്തിടത്തോളം. ഉദാഹരണത്തിന്, ഒരു നിശ്ചിത വർഷത്തിലധികം പഴക്കമുള്ളതും ശരിയായ കസ്റ്റഡിയിൽ നിന്ന് ഹാജരാക്കിയതുമായ ഒരു രേഖ, വേറെ തെളിവില്ലാതെ തന്നെ ഒറിജിനലാണെന്ന് അനുമാനിക്കപ്പെടാം.',
  'interrogatories': 'ഒരു സിവിൽ കേസിലെ ഒരു കക്ഷിക്ക്, മറുകക്ഷിയോട് സത്യപ്രതിജ്ഞയ്ക്ക് കീഴിൽ മറുപടി നൽകാൻ ആവശ്യപ്പെടാവുന്ന രേഖാമൂലമായ ചോദ്യങ്ങളുടെ ഒരു സെറ്റ്, വിചാരണയ്ക്ക് മുൻപ് കേസുമായി ബന്ധപ്പെട്ട വസ്തുതകളോ അംഗീകാരങ്ങളോ നേടാൻ ഉപയോഗിക്കുന്നത്.',
  'discovery-of-documents': 'ഒരു സിവിൽ കേസിലെ ഒരു കക്ഷിക്ക്, വിചാരണ ആരംഭിക്കുന്നതിന് മുൻപ്, കേസുമായി ബന്ധപ്പെട്ട തങ്ങളുടെ കൈവശമുള്ള രേഖകൾ മറുകക്ഷിയോട് വെളിപ്പെടുത്താനും ഹാജരാക്കാനും ആവശ്യപ്പെടാവുന്ന നടപടിക്രമം.',
  'evidence-by-affidavit': 'പ്രധാനമായും ട്രിബ്യൂണലുകൾക്കും കമ്മീഷനുകൾക്കും മുന്നിൽ പിന്തുടരുന്ന ഒരു രീതി, അതിൽ ഒരു സാക്ഷിയുടെ എക്സാമിനേഷൻ-ഇൻ-ചീഫ് കോടതിയിൽ വാചികമായി നൽകുന്നതിന് പകരം ഒരു സത്യം ചെയ്ത സത്യവാങ്മൂലത്തിന്റെ രൂപത്തിൽ ഫയൽ ചെയ്യുന്നു. ആ സത്യവാങ്മൂലത്തിൽ പറഞ്ഞ പ്രസ്താവനകളിൽ സാക്ഷിയെ ഇപ്പോഴും ക്രോസ്-എക്സാമിനേഷന് വിളിക്കാം.',
  'primary-evidence': 'കോടതിയുടെ പരിശോധനയ്ക്ക് ഹാജരാക്കുന്ന ഒറിജിനൽ രേഖ തന്നെ, ഒരു പകർപ്പോ അതിന്റെ ഉള്ളടക്കത്തെക്കുറിച്ചുള്ള വാചികമായ വിവരണമോ പോലുള്ള സെക്കൻഡറി തെളിവിന് വിപരീതമായി. ഒറിജിനൽ രേഖ ലഭ്യമായിടത്തെല്ലാം കോടതികൾ സാധാരണയായി പ്രൈമറി തെളിവ് തന്നെ നിർബന്ധിക്കും.',
  'secondary-evidence': 'ഒറിജിനൽ തന്നെ ഒഴികെയുള്ള ഒരു രേഖയുടെ ഉള്ളടക്കത്തിന്റെ തെളിവ്, ഉദാഹരണത്തിന് ഒരു സർട്ടിഫൈഡ് കോപ്പിയോ അത് കണ്ടിട്ടുള്ള ഒരാളുടെ വാചികമായ വിവരണമോ, ഒറിജിനൽ നഷ്ടപ്പെട്ടതോ മറുകക്ഷിയുടെ കൈവശമായതോ പോലുള്ള പ്രത്യേക സാഹചര്യങ്ങളിൽ മാത്രം അനുവദിക്കുന്നത്.',
  'leading-question': 'സ്വന്തം ഉത്തരം സൂചിപ്പിക്കുന്നതോ സൂചനയായി നൽകുന്നതോ, അല്ലെങ്കിൽ ഇതുവരെ സ്ഥാപിച്ചിട്ടില്ലാത്ത ഒരു വസ്തുത മുൻകൂട്ടി കരുതുന്നതോ ആയ ഒരു ചോദ്യം. ആമുഖമോ തർക്കമില്ലാത്തതോ ആയ കാര്യങ്ങളിലൊഴികെ, ലീഡിംഗ് ചോദ്യങ്ങൾ സാധാരണയായി എക്സാമിനേഷൻ-ഇൻ-ചീഫിൽ അനുവദിക്കില്ല, പക്ഷേ ക്രോസ്-എക്സാമിനേഷനിൽ അനുവദിക്കുന്നു.',
  'test-identification-parade': 'സാധാരണയായി ഒരു മജിസ്ട്രേറ്റ് നടത്തുന്ന ഒരു നടപടിക്രമം, അതിൽ മറ്റ് ആളുകളുടെ ഒരു കൂട്ടത്തിൽ നിന്ന് ഒരു സംശയിക്കപ്പെടുന്നയാളെ തിരഞ്ഞെടുക്കാൻ ഒരു സാക്ഷിയോട് ആവശ്യപ്പെടുന്നു, കുറ്റകൃത്യത്തിൽ ഉൾപ്പെട്ട വ്യക്തിയായി സാക്ഷിക്ക് അവരെ ശരിയായി തിരിച്ചറിയാൻ കഴിയുമോ എന്ന് പരിശോധിക്കാൻ.',
  'dying-declaration': 'ഒരു വ്യക്തി മരിക്കുന്നതിന് മുൻപ്, തന്റെ മരണത്തിന്റെ കാരണത്തെക്കുറിച്ചോ അതിലേക്ക് നയിച്ച സാഹചര്യങ്ങളെക്കുറിച്ചോ നൽകുന്ന പ്രസ്താവന. ഹിയർസേയ്ക്കുള്ള സാധാരണ നിയമത്തിന് ഒരു ഇളവായി കോടതികൾ ഡൈയിംഗ് ഡിക്ലറേഷനെ കണക്കാക്കുന്നു, വിശ്വസനീയമായ ഒന്നിന്റെ അടിസ്ഥാനത്തിൽ മാത്രം ഒരു പ്രതിയെ ശിക്ഷിക്കാനും കഴിയും.',
  'confession': 'ഒരു കുറ്റാരോപിതൻ തന്റെ സ്വന്തം കുറ്റകൃത്യത്തിലെ കുറ്റം അംഗീകരിച്ച് നടത്തുന്ന പ്രസ്താവന, ഒരു സിവിൽ കാര്യത്തിൽ ഒരു കക്ഷി തന്റെ സ്വന്തം താൽപ്പര്യത്തിന് വിരുദ്ധമായ ഒരു വസ്തുത അംഗീകരിക്കുന്ന അഡ്മിഷനിൽ നിന്ന് വ്യത്യസ്തമായി. ഇന്ത്യൻ എവിഡൻസ് ആക്ടിന് പകരം വന്ന എവിഡൻസ് നിയമമായ ഭാരതീയ സാക്ഷ്യ അധിനിയം, 2023 (BSA) പ്രകാരം, മജിസ്ട്രേറ്റിന് മുന്നിൽ അല്ലാതെ, പോലീസിന് മാത്രം നൽകിയ ഒരു കുറ്റസമ്മതം സാധാരണയായി വിചാരണയിൽ പ്രതിക്കെതിരെ ഉപയോഗിക്കാനാവില്ല.',
  'interested-witness': 'കേസിന്റെ ഫലത്തിൽ ചില വ്യക്തിപരമായ താൽപ്പര്യമുള്ള സാക്ഷി, ഉദാഹരണത്തിന് ഒരു കക്ഷിയുടെ അടുത്ത ബന്ധു, അവരുടെ സാക്ഷ്യം കോടതികൾ ആ ബന്ധം മാത്രം കാരണമായി തള്ളിക്കളയാതെ കൂടുതൽ ശ്രദ്ധയോടെ പരിശോധിക്കുന്നത്.',
  'proof-of-document': 'സാധാരണയായി ഒരു സാക്ഷി വഴി, ഒരു രേഖ ഒറിജിനലാണെന്നും അത് അവകാശപ്പെടുന്ന രീതിയിൽ തന്നെ നിർവ്വഹിച്ചതോ സൃഷ്ടിച്ചതോ ആണെന്നും സ്ഥാപിക്കുന്ന പ്രക്രിയ, അതിന്റെ ഉള്ളടക്കത്തെ കോടതിക്ക് ആശ്രയിക്കാൻ കഴിയുന്നതിന് മുൻപ്. ഒരു രേഖ കോടതി റെക്കോർഡിൽ വയ്ക്കുന്നത് മാത്രം അതിനെ തെളിയിക്കുന്നില്ല.',
  'chain-of-custody': 'ഒരു ആയുധമോ ഫോറൻസിക് സാമ്പിളോ പോലുള്ള ഒരു ഭൗതിക വസ്തുവോ സാമ്പിളോ കൈകാര്യം ചെയ്തവരുടെയോ അതിന്റെ നിയന്ത്രണത്തിലുണ്ടായിരുന്നവരുടെയോ, അത് പിടിച്ചെടുത്ത സമയം മുതൽ കോടതിയിൽ ഹാജരാക്കുന്നതുവരെയുള്ള ഒരു രേഖപ്പെടുത്തിയ റെക്കോർഡ്. ചെയിൻ ഓഫ് കസ്റ്റഡിയിൽ ഉണ്ടാകുന്ന വിടവുകളോ മോശമായ രേഖപ്പെടുത്തലോ, ഹാജരാക്കിയ തെളിവ് യഥാർത്ഥത്തിൽ പിടിച്ചെടുത്തതുതന്നെയാണോ എന്നതിൽ സംശയം ഉണ്ടാക്കാം.',

  'first-information-report': 'ഒരു ക്രിമിനൽ അന്വേഷണത്തിന്റെ ഔപചാരികമായ ആരംഭം അടയാളപ്പെടുത്തി, ഒരു കോഗ്നിസബിൾ കുറ്റകൃത്യത്തെക്കുറിച്ച് പോലീസിന് ആദ്യം വിവരം ലഭിക്കുമ്പോൾ അവർ തയ്യാറാക്കുന്ന രേഖാമൂലമായ റെക്കോർഡ്. CrPC ക്ക് പകരം വന്ന കോഡായ ഭാരതീയ നാഗരിക് സുരക്ഷാ സംഹിത, 2023 (BNSS) പ്രകാരമാണ് ഇത് ഫയൽ ചെയ്യുന്നത്.',
  'chargesheet': 'അന്വേഷണത്തിന്റെ അവസാനത്തിൽ പോലീസ് മജിസ്ട്രേറ്റിന് ഫയൽ ചെയ്യുന്ന റിപ്പോർട്ട്, ശേഖരിച്ച തെളിവുകൾ വിശദീകരിക്കുകയും, അത് ഒരു കേസിനെ പിന്തുണയ്ക്കുന്നെങ്കിൽ, വിചാരണ ചെയ്യേണ്ട കുറ്റാരോപിതരെ പേരെടുത്ത് പറയുകയും ചെയ്യുന്നത്. CrPC ക്ക് പകരം വന്ന BNSS പ്രകാരം ഇതിനെ ഔപചാരികമായി പോലീസ് റിപ്പോർട്ട് അല്ലെങ്കിൽ ഫൈനൽ റിപ്പോർട്ട് എന്ന് വിളിക്കുന്നു.',
  'bail': 'ഒരു കുറ്റകൃത്യത്തിന് കുറ്റാരോപിതനായ വ്യക്തിയെ, വിചാരണ അല്ലെങ്കിൽ തുടർ നടപടികൾ നിലവിലിരിക്കുന്നതിനിടെ, സാധാരണയായി ഒരു ബോണ്ടോ ജാമ്യക്കാരനോ പോലുള്ള നിബന്ധനകളിൽ കസ്റ്റഡിയിൽ നിന്ന് മോചിപ്പിക്കൽ. ഇത് ഒരു കുറ്റവിമുക്തിയോ നിരപരാധിത്വത്തിന്റെ കണ്ടെത്തലോ അല്ല, കേസ് തുടരുമ്പോൾ കസ്റ്റഡിയിൽ നിന്നുള്ള മോചനം മാത്രമാണ്.',
  'anticipatory-bail': 'ഒരാളെ യഥാർത്ഥത്തിൽ അറസ്റ്റ് ചെയ്യുന്നതിന് മുൻപ് മുൻകൂട്ടി നൽകുന്ന കോടതി ഉത്തരവ്, ഒരു പ്രത്യേക ആരോപണത്തിൽ അറസ്റ്റ് ചെയ്താൽ ജാമ്യത്തിൽ വിട്ടയക്കണമെന്ന് നിർദ്ദേശിക്കുന്നത്. തെറ്റായോ അന്യായമായോ അറസ്റ്റ് ചെയ്യപ്പെടാമെന്ന് കരുതാൻ കാരണമുള്ള ഒരാളെ സംരക്ഷിക്കാനാണ് ഇത് ഉദ്ദേശിക്കുന്നത്.',
  'cognizable-offence': 'സാധാരണയായി കൂടുതൽ ഗൗരവമുള്ള ഒരു തരം കുറ്റകൃത്യം, അതിൽ പോലീസിന് മജിസ്ട്രേറ്റിന്റെ മുൻകൂർ അനുമതി ആവശ്യമില്ലാതെ FIR രജിസ്റ്റർ ചെയ്യാനും അന്വേഷണം ആരംഭിക്കാനും കുറ്റാരോപിതനെ അറസ്റ്റ് ചെയ്യാനും കഴിയും.',
  'non-cognizable-offence': 'സാധാരണയായി കുറഞ്ഞ ഗൗരവമുള്ള ഒരു തരം കുറ്റകൃത്യം, അതിൽ ആദ്യം മജിസ്ട്രേറ്റിന്റെ അനുമതി ലഭിക്കാതെ പോലീസിന് കുറ്റാരോപിതനെ അന്വേഷിക്കാനോ അറസ്റ്റ് ചെയ്യാനോ കഴിയില്ല. ഇത്തരം ഒരു കേസിലെ പരാതിക്കാരൻ സാധാരണയായി പോലീസ് സ്റ്റേഷനിൽ ഒരു FIR ഫയൽ ചെയ്യുന്നതിന് പകരം നേരിട്ട് മജിസ്ട്രേറ്റിനെ സമീപിക്കേണ്ടിവരും.',
  'summons': 'ഒരു നിശ്ചിത തീയതിയിൽ കോടതിയിൽ ഹാജരാകാൻ ഒരു വ്യക്തിയെ നിർദ്ദേശിക്കുന്ന ഔപചാരികമായ കോടതി ഉത്തരവ്, ആ വ്യക്തിയെ അറസ്റ്റ് ചെയ്യേണ്ടത് ആവശ്യമില്ലെന്ന് കോടതി കരുതുമ്പോൾ ഉപയോഗിക്കുന്നത്. സമൻസ് അവഗണിക്കുന്നത്, വാറന്റ് ഉൾപ്പെടെ, കോടതിയെ കൂടുതൽ കർശനമായ നടപടികളിലേക്ക് നീങ്ങാൻ ഇടയാക്കാം.',
  'warrant': 'ഒരു വ്യക്തിയെ അറസ്റ്റ് ചെയ്ത് കോടതിയിൽ ഹാജരാക്കാൻ പോലീസിന് നിർദ്ദേശിക്കുന്ന കോടതി നൽകുന്ന രേഖാമൂലമായ ഉത്തരവ്. ഒരു "ജാമ്യ" വാറന്റ് അറസ്റ്റ് ചെയ്ത ഉടൻ തന്നെ ആ വ്യക്തിയെ ജാമ്യത്തിൽ വിട്ടയക്കാൻ അനുവദിക്കുന്നു, അതേസമയം ഒരു "ജാമ്യമില്ലാ" വാറന്റ് അവരെ ആദ്യം കോടതിയിൽ ഹാജരാക്കണമെന്ന് ആവശ്യപ്പെടുന്നു.',
  'remand': 'അറസ്റ്റ് ചെയ്ത ഒരു വ്യക്തിയെ, അന്വേഷണത്തിനോ വിചാരണയ്ക്കോ തുടരുന്ന കാലയളവിൽ, ഒന്നുകിൽ കൂടുതൽ അന്വേഷണത്തിന് പോലീസ് കസ്റ്റഡിയിലേക്കോ ജുഡീഷ്യൽ കസ്റ്റഡിയിലേക്കോ അയയ്ക്കുന്ന ഒരു പരിമിതമായ കാലയളവിലേക്കുള്ള ഉത്തരവ്.',
  'discharge-criminal': 'വിചാരണയ്ക്ക് മുൻപ് ഒരു ക്രിമിനൽ കേസിൽ നിന്ന് ഒരു കുറ്റാരോപിതനെ കോടതി മോചിപ്പിക്കുന്ന ഉത്തരവ്, കുറ്റാരോപിതനെതിരെ മുന്നോട്ടുപോകാൻ, മുഖവിലയ്‌ക്കെടുത്തുപോലും, മതിയായ തെളിവില്ലെന്ന് കോടതി കണ്ടെത്തുന്നതുകൊണ്ട്. ഒരു ഡിസ്ചാർജ് ഒരു അക്വിറ്റൽ അല്ല, അത് തെളിവിന്റെ അടിസ്ഥാനത്തിൽ പൂർണ്ണ വിചാരണയ്ക്ക് ശേഷം മാത്രം വരുന്നതാണ്.',
  'acquittal': 'പൂർണ്ണ വിചാരണയ്ക്ക് ശേഷം, കുറ്റാരോപിതൻ ആരോപിക്കപ്പെട്ട കുറ്റത്തിൽ കുറ്റക്കാരനല്ലെന്ന കോടതിയുടെ അന്തിമമായ കണ്ടെത്തൽ. ഇത് കുറ്റാരോപിതനെ ആ കുറ്റത്തിൽ നിന്ന് മോചിപ്പിക്കുന്നു, പരിമിതമായ ഇളവുകൾക്ക് വിധേയമായി, അതേ കുറ്റത്തിന് അവരെ പൊതുവെ വീണ്ടും വിചാരണ ചെയ്യാനാവില്ല.',
  'complainant': 'ഒരു കുറ്റകൃത്യം നടന്നതായി ആരോപിച്ച്, ഒരു ക്രിമിനൽ പരാതി കോടതിയിലോ പോലീസ് സ്റ്റേഷനിലോ കൊണ്ടുവരുന്ന വ്യക്തി, ആരോപണം ഉന്നയിച്ചിരിക്കുന്ന കുറ്റാരോപിതനിൽ നിന്ന് വ്യത്യസ്തമായി.',
  'accused': 'ഒരു കുറ്റകൃത്യത്തിന് ഒരു ക്രിമിനൽ ആരോപണം നേരിടുന്ന, അതിന്റെ അടിസ്ഥാനത്തിൽ അന്വേഷിക്കപ്പെടുന്നതോ കുറ്റം ചുമത്തപ്പെടുന്നതോ വിചാരണ ചെയ്യപ്പെടുന്നതോ ആയ വ്യക്തി. കോടതി കുറ്റക്കാരനെന്ന് തെളിയിക്കുന്നതുവരെ ഒരു കുറ്റാരോപിതൻ നിരപരാധിയായി കണക്കാക്കപ്പെടുന്നു.',
  'investigating-officer': 'ഒരു ക്രിമിനൽ കേസ് അന്വേഷിക്കുന്ന ഉത്തരവാദിത്തമുള്ള പോലീസ് ഉദ്യോഗസ്ഥൻ, തെളിവുകൾ ശേഖരിക്കൽ, സാക്ഷി പ്രസ്താവനകൾ രേഖപ്പെടുത്തൽ, ഒടുവിൽ ചാർജ്ഷീറ്റ് ഫയൽ ചെയ്യൽ അല്ലെങ്കിൽ കേസ് അവസാനിപ്പിക്കൽ എന്നിവ ഉൾപ്പെടെ.',
  'cognizance': 'ഒരു മജിസ്ട്രേറ്റ് ഒരു കുറ്റകൃത്യത്തെ ജുഡീഷ്യൽ ആയി അറിയുകയും, ഒരു പരാതിയുടെയോ പോലീസ് റിപ്പോർട്ടിന്റെയോ മജിസ്ട്രേറ്റിന്റെ സ്വന്തം വിവരത്തിന്റെയോ അടിസ്ഥാനത്തിൽ കേസ് മുന്നോട്ടുകൊണ്ടുപോകാൻ തീരുമാനിക്കുകയും ചെയ്യുന്ന ഔപചാരികമായ ഘട്ടം. കോഗ്‌നിസൻസ് എടുക്കുന്നതുവരെ, ആ കോടതിക്ക് മുന്നിൽ ഒരു വിഷയം ഔപചാരികമായി ഒരു കേസായി മാറിയിട്ടില്ല.',
  'framing-of-charge': 'കുറ്റാരോപിതൻ ചെയ്തതായി ആരോപിക്കപ്പെടുന്ന പ്രത്യേക കുറ്റമോ കുറ്റങ്ങളോ, ഇതുവരെ ലഭ്യമായ തെളിവുകളുടെ അടിസ്ഥാനത്തിൽ, കോടതി ഔപചാരികമായി രേഖാമൂലം വ്യക്തമാക്കുന്ന ഘട്ടം. ഈ രൂപപ്പെടുത്തിയ കുറ്റങ്ങളുടെ അടിസ്ഥാനത്തിലാണ് വിചാരണ നടക്കുന്നത്, കുറ്റാരോപിതനോട് അവയ്ക്ക് കുറ്റക്കാരനാണെന്നോ അല്ലെന്നോ വാദിക്കാൻ ആവശ്യപ്പെടുന്നു.',
  'compounding-of-offence': 'പരാതിക്കാരനും കുറ്റാരോപിതനും ചേർന്ന്, ആവശ്യമുള്ളിടത്ത് കോടതിയുടെ അനുമതിയോടെ, ചില ക്രിമിനൽ കേസുകൾ തമ്മിൽ തീർപ്പാക്കുന്ന പ്രക്രിയ, പൂർണ്ണ വിചാരണയില്ലാതെ കേസ് അവസാനിപ്പിക്കുന്നത്. നിയമം പ്രത്യേകമായി കോംപൗണ്ട് ചെയ്യാൻ അനുവദിക്കുന്ന കുറ്റകൃത്യങ്ങൾ മാത്രമേ ഈ വിധം തീർപ്പാക്കാനാകൂ; ഗൗരവമുള്ള കുറ്റകൃത്യങ്ങൾ സാധാരണയായി കഴിയില്ല.',
  'zero-fir': 'ഒരു കോഗ്നിസബിൾ കുറ്റകൃത്യത്തിന്, ആ പോലീസ് സ്റ്റേഷന്റെ അധികാരപരിധിയിൽ സംഭവസ്ഥലം വരുന്നില്ലെങ്കിലും, ഏതൊരു പോലീസ് സ്റ്റേഷനും രജിസ്റ്റർ ചെയ്യുന്ന FIR. പിന്നീട് ഇത് അന്വേഷണത്തിനായി ശരിയായ അധികാരപരിധിയുള്ള പോലീസ് സ്റ്റേഷനിലേക്ക് മാറ്റുന്നു.',
  'quashing-of-fir': 'ഹൈക്കോടതിയുടെ അന്തർലീനമായ അധികാരം ഉപയോഗിച്ച്, ഒരു FIR യോ നടന്നുകൊണ്ടിരിക്കുന്ന ക്രിമിനൽ നടപടികളോ റദ്ദാക്കണമെന്ന് ആവശ്യപ്പെടുന്ന ഒരു ഹർജി, സാധാരണയായി അവ അടിസ്ഥാനമില്ലാത്തതോ നിയമ നടപടിയുടെ ദുരുപയോഗമോ, അല്ലെങ്കിൽ തർക്കം കക്ഷികൾക്കിടയിൽ ഇതിനകം യഥാർത്ഥത്തിൽ തീർപ്പാക്കിയതോ ആണെന്ന കാരണത്തിൽ.',
  'plea-bargaining': 'ചില വിഭാഗം കുറ്റകൃത്യങ്ങൾക്ക് മാത്രം ലഭ്യമായ, ഒരു കുറ്റാരോപിതൻ കുറ്റം സമ്മതിക്കുന്നതിന് പകരമായി കുറഞ്ഞ ശിക്ഷയ്ക്ക് വേണ്ടി ചർച്ച ചെയ്യാൻ അപേക്ഷിക്കാവുന്ന, ഭാരതീയ നാഗരിക് സുരക്ഷാ സംഹിത, 2023 (BNSS) പ്രകാരമുള്ള ഒരു പ്രക്രിയ.',
  'default-bail': 'നിശ്ചിത കാലയളവിനകം അന്വേഷണം പൂർത്തിയാക്കി ചാർജ്ഷീറ്റ് ഫയൽ ചെയ്യുന്നതിൽ പോലീസ് പരാജയപ്പെടുമ്പോൾ, ഭാരതീയ നാഗരിക് സുരക്ഷാ സംഹിത, 2023 (BNSS) പ്രകാരം അനുവദിച്ച സമയത്തിനകം, ആരോപണം എത്ര ഗൗരവമായാലും, ഒരു കുറ്റാരോപിതന് അവകാശമായി ലഭിക്കുന്ന ജാമ്യം.',
  'bail-bond': 'ജാമ്യത്തിൽ വിട്ടയക്കപ്പെടുമ്പോൾ ഒരു കുറ്റാരോപിതൻ നിർവ്വഹിക്കുന്ന രേഖ, ആവശ്യപ്പെടുന്നതനുസരിച്ച് കോടതിയിൽ ഹാജരാകുമെന്ന് ഉടമ്പടി ചെയ്യുന്നത്, പലപ്പോഴും ഒന്നോ അതിലധികമോ ജാമ്യക്കാരുമായി ചേർന്ന്, അവർ ഹാജരാകുന്നതിൽ പരാജയപ്പെട്ടാൽ കുറ്റാരോപിതനെ ഹാജരാക്കാമെന്നോ ഒരു നിശ്ചിത തുക നഷ്ടപ്പെടുത്താമെന്നോ ഉടമ്പടി ചെയ്യുന്നത്.',
  'private-complaint': 'പോലീസ് വഴിയല്ലാതെ, ഒരു സ്വകാര്യ വ്യക്തി നേരിട്ട് മജിസ്ട്രേറ്റിന് മുന്നിൽ ഫയൽ ചെയ്യുന്ന ക്രിമിനൽ പരാതി, സാധാരണയായി നോൺ-കോഗ്നിസബിൾ കുറ്റകൃത്യങ്ങൾക്കോ ഒരു കോഗ്നിസബിൾ കുറ്റകൃത്യത്തിന് FIR രജിസ്റ്റർ ചെയ്യാൻ പോലീസ് വിസമ്മതിച്ചിടത്തോ ഉപയോഗിക്കുന്നത്.',
  'proclaimed-offender': 'അറസ്റ്റ് ഒഴിവാക്കാൻ ഒളിച്ചോടിയതായോ ഒളിച്ചതായോ ഒരു കോടതി ഔപചാരികമായി പ്രഖ്യാപിച്ച വ്യക്തി, അതിന് ശേഷം അയാൾ ഹാജരാകുന്നതുവരെ അയാളുടെ സ്വത്ത് കണ്ടുകെട്ടൽ ഉൾപ്പെടെ കൂടുതൽ നടപടികൾ കോടതിക്ക് സ്വീകരിക്കാം.',
  'conviction': 'വിചാരണയ്ക്ക് ശേഷം, കുറ്റാരോപിതൻ ആരോപിക്കപ്പെട്ട കുറ്റത്തിൽ കുറ്റക്കാരനാണെന്ന കോടതിയുടെ അന്തിമമായ കണ്ടെത്തൽ, ഇത് കോടതി ഒരു ശിക്ഷ നൽകുന്നതിലേക്ക് നയിക്കുന്നു. ഇത് അക്വിറ്റലിന്റെ വിപരീത ഫലമാണ്.',
  'sentence': 'ഒരു കുറ്റകൃത്യത്തിന് ഒരു വ്യക്തിയെ കുറ്റക്കാരനെന്ന് കണ്ടെത്തിയ ശേഷം കോടതി നൽകുന്ന ശിക്ഷ, ഉദാഹരണത്തിന് തടവോ പിഴയോ. ശിക്ഷ നൽകുന്നതിന് മുൻപ്, ഉചിതമായ ശിക്ഷയെക്കുറിച്ച് കോടതികൾ സാധാരണയായി കുറ്റക്കാരനാക്കപ്പെട്ട വ്യക്തിയെ വേറെ കേൾക്കും.',
  'probation': 'ഒരു ശിക്ഷ അനുഭവിക്കാൻ വിടുന്നതിന് പകരം, നല്ല പെരുമാറ്റത്തിൽ, കോടതി നിശ്ചയിച്ച മേൽനോട്ടത്തിലും നിബന്ധനകളിലും ഒരു കുറ്റക്കാരനാക്കപ്പെട്ട വ്യക്തിയെ വിട്ടയക്കുന്ന ഉത്തരവ്. ആദ്യമായി കുറ്റകൃത്യം ചെയ്തവർക്കോ കുറഞ്ഞ ഗൗരവമുള്ള കുറ്റകൃത്യങ്ങൾക്കോ ഇത് സാധാരണയായി പരിഗണിക്കുന്നു.',
  'status-report': 'ഒരു കേസ് അന്വേഷിക്കുന്നതിലെ പുരോഗതി കോടതിയെ അപ്ഡേറ്റ് ചെയ്യാൻ, കോടതിയുടെ നിർദ്ദേശപ്രകാരം, പോലീസ് ഫയൽ ചെയ്യുന്ന റിപ്പോർട്ട്.',
  'closure-report': 'അന്വേഷണത്തിന്റെ അവസാനത്തിൽ, പേരെടുത്ത സംശയിക്കപ്പെടുന്നവർക്കെതിരെ ഒരു കേസും ഇല്ലെന്നും, വിഷയം വിചാരണയിലേക്ക് പോകരുതെന്നും പ്രസ്താവിച്ച് പോലീസ് ഫയൽ ചെയ്യുന്ന റിപ്പോർട്ട്. CrPC ക്ക് പകരം വന്ന കോഡായ ഭാരതീയ നാഗരിക് സുരക്ഷാ സംഹിത, 2023 (BNSS) പ്രകാരമാണ് ഇത് ഫയൽ ചെയ്യുന്നത്, മജിസ്ട്രേറ്റ് ഇത് സ്വീകരിക്കുന്നതിന് മുൻപ് പരാതിക്കാരന് കേൾക്കപ്പെടാനുള്ള അവകാശമുണ്ട്.',
  'protest-petition': 'ഒരു ക്ലോഷർ റിപ്പോർട്ടിനെ ചോദ്യം ചെയ്ത്, അത് സ്വീകരിക്കരുതെന്നും പകരം കുറ്റകൃത്യത്തിന്റെ കോഗ്‌നിസൻസ് എടുത്ത് കേസ് മുന്നോട്ടുകൊണ്ടുപോകണമെന്നും മജിസ്ട്രേറ്റിനോട് ആവശ്യപ്പെട്ട്, പരാതിക്കാരൻ ഫയൽ ചെയ്യുന്ന എതിർപ്പ്.',

  'temporary-injunction': 'ഒരു പ്രധാന കേസ് ഇപ്പോഴും തീരുമാനിച്ചുകൊണ്ടിരിക്കുമ്പോൾ, ഒരു തർക്കത്തിലുള്ള സ്വത്ത് വിൽക്കുന്നത് പോലുള്ള ഒരു പ്രത്യേക പ്രവൃത്തി ചെയ്യുന്നതിൽ നിന്ന് ഒരു കക്ഷിയെ താൽക്കാലികമായി തടയുന്ന കോടതി ഉത്തരവ്. അതിനിടയിൽ സ്വീകരിച്ച നടപടികൾ അന്തിമ തീരുമാനത്തെ അർത്ഥശൂന്യമാക്കാതിരിക്കാൻ, സ്ഥിതി അതേപടി സംരക്ഷിക്കാനാണ് ഇത് ഉദ്ദേശിക്കുന്നത്.',
  'permanent-injunction': 'ഒരു കേസിന്റെ അവസാനത്തിൽ നൽകുന്ന അന്തിമ കോടതി ഉത്തരവ്, ഒരു പ്രത്യേക പ്രവൃത്തി ചെയ്യുന്നതിൽ നിന്ന് ഒരു കക്ഷിയെ ശാശ്വതമായി തടയുന്നത്. ഒരു ടെമ്പററി ഇൻജങ്ഷനിൽ നിന്ന് വ്യത്യസ്തമായി, ഇത് ഒരു താൽക്കാലിക നടപടിയല്ല, കേസിന്റെ അന്തിമ തീരുമാനത്തിന്റെ ഭാഗമാണ്.',
  'specific-performance': 'ഒരു പ്രത്യേക സ്വത്തിന്റെ വിൽപ്പന പൂർത്തിയാക്കുന്നത് പോലുള്ള, ഒരു കരാറിന് കീഴിലുള്ള തങ്ങളുടെ ബാധ്യതകൾ ഒരു കക്ഷി യഥാർത്ഥത്തിൽ നിർവ്വഹിക്കണമെന്ന് നിർദ്ദേശിക്കുന്ന കോടതി ഉത്തരവ്, അത് ലംഘിച്ചതിന് വെറുതെ നഷ്ടപരിഹാരം നൽകുന്നതിന് പകരം. പണം മാത്രം ലംഘനത്തിന് മതിയായ പരിഹാരമല്ലെന്ന് തോന്നുമ്പോൾ മാത്രമാണ് കോടതികൾ ഈ പരിഹാരം നൽകുന്നത്.',
  'damages': 'ഒരു കരാർ ലംഘനമോ ടോർട്ടോ പോലുള്ള ഒരു തെറ്റുകൊണ്ടുണ്ടായ നഷ്ടത്തിനോ പരിക്കിനോ നഷ്ടപരിഹാരമായി ഒരു കക്ഷി മറ്റൊരു കക്ഷിക്ക് നൽകണമെന്ന് കോടതി ഉത്തരവിടുന്ന ഒരു തുക. പണത്തിന് കഴിയുന്നിടത്തോളം, തെറ്റ് സംഭവിച്ചില്ലായിരുന്നെങ്കിൽ ഉണ്ടാകുമായിരുന്ന സ്ഥാനത്ത് നഷ്ടപ്പെട്ട കക്ഷിയെ തിരികെ കൊണ്ടുവരാനാണ് ഈ തുക ഉദ്ദേശിക്കുന്നത്.',
  'preliminary-decree': 'കക്ഷികളുടെ അവകാശങ്ങൾ ഒരു വിഷയത്തിൽ തീരുമാനിക്കുന്ന, എന്നാൽ അക്കൗണ്ടിംഗോ സ്വത്ത് വിഭജനമോ പോലുള്ള ചില തുടർ നടപടികൾ, കേസ് പൂർണ്ണമായി അടയ്ക്കുന്നതിന് മുൻപ് നിർവ്വഹിക്കാനായി ബാക്കിവയ്ക്കുന്ന ഒരു ഡിക്രി. ആ ബാക്കിയുള്ള നടപടികൾ പൂർത്തിയായ ശേഷം ഒരു ഫൈനൽ ഡിക്രി ഇതിനെ തുടരും.',
  'final-decree': 'ഒരു പ്രിലിമിനറി ഡിക്രിക്ക് ശേഷമോ, നേരിട്ടോ, സ്വത്തിന്റെ കൃത്യമായ വിഭജനം പോലുള്ള ബാക്കിയുള്ള ചോദ്യങ്ങളെല്ലാം തീർപ്പാക്കിയ ശേഷം ഒരു സ്യൂട്ട് പൂർണ്ണമായി തീർപ്പാക്കുന്ന ഡിക്രി.',
  'execution-of-decree': 'ഒരു കേസ് ജയിച്ച കക്ഷി, കോടതിയുടെ ഡിക്രി യഥാർത്ഥത്തിൽ നടപ്പിലാക്കിക്കുന്ന നിയമപ്രക്രിയ, ഉദാഹരണത്തിന് തോൽവി സംഭവിച്ച കക്ഷിയുടെ സ്വത്ത് പിടിച്ചെടുത്തോ കുടിശ്ശികയായ പണം തിരിച്ചുപിടിച്ചോ. ഒരു കേസ് ജയിക്കുന്നത് ആശ്വാസം സ്വയം ലഭിക്കുമെന്ന് അർത്ഥമാക്കുന്നില്ല; അത് പ്രയോഗത്തിൽ കൊണ്ടുവരാൻ പലപ്പോഴും നിർവ്വഹണ നടപടികൾ ആവശ്യമായി വരും.',
  'review-civil': 'ഒരു വിധിയോ ഉത്തരവോ നൽകിയ അതേ കോടതിയോട് തന്നെ, സാധാരണയായി റെക്കോർഡിൽ വ്യക്തമായ വസ്തുതാപരമോ നിയമപരമോ ആയ പിഴവ് കാരണമോ പുതുതായി കണ്ടെത്തിയ തെളിവ് കാരണമോ, സ്വന്തം തീരുമാനം പുനഃപരിശോധിക്കാൻ ആവശ്യപ്പെടുന്ന അപേക്ഷ. ഉയർന്ന കോടതി കേൾക്കുന്ന അപ്പീലിനേക്കാളും, ഒരു ലോവർ കോടതി അധികാരപരിധിക്കുള്ളിൽ പ്രവർത്തിച്ചോ എന്ന് പരിശോധിക്കുന്ന റിവിഷനേക്കാളും ഇതിന്റെ പരിധി ചുരുങ്ങിയതാണ്.',
  'revision-civil': 'ഒരു ലോവർ കോടതി ഒരു കേസിൽ അധികാരപരിധിക്കുള്ളിൽ പ്രവർത്തിച്ചോ, ശരിയായ നടപടിക്രമം പാലിച്ചോ എന്ന് പരിശോധിക്കാൻ ഉയർന്ന കോടതിയോട് ആവശ്യപ്പെടുന്ന അപേക്ഷ, വസ്തുതകളിലെ അതിന്റെ കണ്ടെത്തലുകളുടെ ശരിയായത് വീണ്ടും പരിശോധിക്കുന്നതിന് പകരം. തീരുമാനത്തിന്റെ തന്നെ മെറിറ്റിലേക്ക് പോകാൻ കഴിയുന്ന അപ്പീലിനേക്കാൾ ഇതിന്റെ പരിധി പരിമിതമാണ്.',
  'appeal': 'ഒരു ലോവർ കോടതിയുടെ തീരുമാനം, വസ്തുതയിലെയും നിയമത്തിലെയും അതിന്റെ കണ്ടെത്തലുകൾ ഉൾപ്പെടെ, അതിന്റെ മെറിറ്റിൽ അവലോകനം ചെയ്ത് മറികടക്കാൻ ഉയർന്ന കോടതിയോട് ആവശ്യപ്പെടുന്ന അപേക്ഷ. ലോവർ കോടതി അധികാരപരിധിക്കുള്ളിൽ തുടർന്നോ ശരിയായ നടപടിക്രമം പാലിച്ചോ എന്ന് പ്രധാനമായും പരിശോധിക്കുന്ന റിവിഷനേക്കാളും, അതേ കോടതിയോട് തന്നെ വ്യക്തമായ പിഴവിന് സ്വന്തം തീരുമാനം പുനഃപരിശോധിക്കാൻ ആവശ്യപ്പെടുന്ന റിവ്യൂവിനേക്കാളും ഇത് വിശാലമാണ്.',
  'suit-for-recovery': 'ഒരാൾ മറ്റൊരാൾക്ക് കടപ്പെട്ടിരിക്കുന്ന ഒരു തുക തിരിച്ചുപിടിക്കാൻ ഫയൽ ചെയ്യുന്ന സിവിൽ കേസ്, ഉദാഹരണത്തിന് ഒടുക്കാത്ത ഒരു ലോൺ, കരാറിന് കീഴിലുള്ള ഒടുക്കാത്ത കുടിശ്ശിക, അല്ലെങ്കിൽ വിറ്റ സാധനങ്ങളുടെ വില.',
  'declaratory-suit': 'ഒരു വ്യക്തി കോടതിയോട് തങ്ങളുടെ നിയമപരമായ അവകാശമോ നിലയോ, ഉദാഹരണത്തിന് ഒരു സ്വത്തിലെ തങ്ങളുടെ ടൈറ്റിൽ, ഔപചാരികമായി പ്രഖ്യാപിക്കാൻ ആവശ്യപ്പെടുന്ന സിവിൽ കേസ്, കൈവശം തിരിച്ചുപിടിക്കുന്നതുപോലുള്ള കൂടുതൽ ഒരു ആശ്വാസം ഉത്തരവിടാനും കോടതിയോട് ആവശ്യപ്പെടുന്നതിന് പകരം.',
  'partition-suit': 'ഒരു സ്വത്തിന്റെ സഹ ഉടമ, ഏറ്റവും സാധാരണയായി കുടുംബാംഗങ്ങൾക്കിടയിൽ, സ്വത്ത് വിഭജിച്ച് ഓരോ ഉടമയുടെയും പ്രത്യേക ഓഹരി അടയാളപ്പെടുത്താൻ കോടതിയോട് ആവശ്യപ്പെട്ട് ഫയൽ ചെയ്യുന്ന സിവിൽ കേസ്.',
  'restitution': 'അപ്പീലിൽ പിന്നീട് മാറ്റപ്പെട്ടതോ ഭേദഗതി ചെയ്തതോ ആയ ഒരു ഡിക്രിക്കോ ഉത്തരവിനോ മുൻപ് ഒരു കക്ഷി ഉണ്ടായിരുന്ന സ്ഥാനത്തേക്ക് അവരെ തിരികെ കൊണ്ടുവരുന്ന ഉത്തരവ്, സാധാരണയായി മറുകക്ഷിയോട് അതിന്റെ അടിസ്ഥാനത്തിൽ തങ്ങൾ സ്വീകരിച്ച പണമോ സ്വത്തോ തിരികെ നൽകാൻ ആവശ്യപ്പെട്ടുകൊണ്ട്.',
  'set-off-and-counterclaim': 'ഒരു സെറ്റ്-ഓഫ് വാദിക്ക് മറ്റൊരു കടമായി കടപ്പെട്ടിരിക്കുന്ന ഒരു പ്രത്യേക കടത്തിലേക്ക് വിരൽ ചൂണ്ടി, പ്രതിക്ക് വാദിയോട് കടപ്പെട്ടിരിക്കുന്നത് കുറയ്ക്കാനോ ഇല്ലാതാക്കാനോ അനുവദിക്കുന്നു. ഒരു കൗണ്ടർക്ലെയിം ഇതിലും കൂടുതൽ മുന്നോട്ടുപോയി, ഒരു പ്രത്യേക സ്യൂട്ട് ഫയൽ ചെയ്യുന്നതിന് പകരം അതേ കേസിൽ തന്നെ വാദിക്കെതിരെ പ്രതിയുടെ സ്വന്തം സ്വതന്ത്ര ക്ലെയിം ഉന്നയിക്കാൻ അനുവദിക്കുന്നു.',
  'mesne-profits': 'മറ്റൊരാളുടെ സ്വത്ത് തെറ്റായി കൈവശം വച്ച് ഉപയോഗിച്ചതിന്, അയാൾക്ക് ലഭിച്ച ലാഭത്തിന്റെയോ പ്രയോജനത്തിന്റെയോ അടിസ്ഥാനത്തിൽ, അല്ലെങ്കിൽ ആ തെറ്റായ കൈവശ കാലയളവിൽ യഥാർത്ഥ ഉടമയ്ക്ക് നഷ്ടപ്പെട്ടതിന്റെ അടിസ്ഥാനത്തിൽ, ഒരു വ്യക്തിയോട് കോടതിക്ക് നൽകാൻ നിർദ്ദേശിക്കാവുന്ന നഷ്ടപരിഹാരം.',
  'rejection-of-plaint': 'പ്ലെയിന്റ് തന്നെ ഒരു അടിസ്ഥാന പിഴവ് കൊണ്ട്, ഉദാഹരണത്തിന് ഒരു കോസ് ഓഫ് ആക്ഷൻ വെളിപ്പെടുത്താത്തതോ മതിയായ സ്റ്റാമ്പ് ചെയ്യാത്തതോ ആയ കാരണത്താൽ, പൂർണ്ണ വിചാരണയിലേക്ക് പോകാതെ, ഒരു സ്യൂട്ടുമായി മുന്നോട്ടുപോകാൻ കോടതി വിസമ്മതിക്കുന്ന ഉത്തരവ്. വിചാരണയ്ക്ക് ശേഷമുള്ള ഡിസ്മിസലിൽ നിന്ന് വ്യത്യസ്തമായി, ചില സാഹചര്യങ്ങളിൽ, അതേ കോസ് ഓഫ് ആക്ഷനിൽ ഒരു പുതിയ സ്യൂട്ട് ഫയൽ ചെയ്യാൻ ഇത് വാദിയെ സ്വതന്ത്രനായി വിടുന്നു.',
  'return-of-plaint': 'കോടതിക്ക് സ്യൂട്ട് വിചാരണ ചെയ്യാൻ അധികാരപരിധി ഇല്ലെന്ന് കണ്ടെത്തുമ്പോൾ നൽകുന്ന ഉത്തരവ്, ശരിയായ കോടതിയിൽ ഹാജരാക്കാനായി പ്ലെയിന്റ് വാദിക്ക് തിരികെ നൽകുന്നത്. അതേ പ്ലെയിന്റ് ശരിയായ കോടതിയിൽ വാദിക്ക് പിന്നീട് വീണ്ടും ഫയൽ ചെയ്യാം.',
  'mandatory-injunction': 'ഒരു പ്രത്യേക പ്രവൃത്തി ചെയ്യുന്നതിൽ നിന്ന് ഒരു കക്ഷിയെ തടയുന്നതിന് പകരം, ഒരു കൈയേറ്റം നീക്കം ചെയ്യുന്നതോ തകർത്ത ഒരു നിർമ്മാണം പുനഃസ്ഥാപിക്കുന്നതോ പോലുള്ള ഒരു പ്രത്യേക പ്രവൃത്തി സജീവമായി ചെയ്യാൻ ഒരു കക്ഷിയെ നിർദ്ദേശിക്കുന്ന കോടതി ഉത്തരവ്. ഒരു കക്ഷിയെ പ്രവർത്തിക്കുന്നതിൽ നിന്ന് മാത്രം തടയുന്ന പ്രൊഹിബിറ്ററി ഇൻജങ്ഷനിൽ നിന്ന് ഇതിനെ വേർതിരിക്കുന്നു.',
  'interpleader-suit': 'രണ്ടോ അതിലധികമോ മറ്റ് ആളുകൾ ആവശ്യപ്പെടുന്ന പണമോ സ്വത്തോ കൈവശം വച്ചിരിക്കുന്ന ഒരാൾ, അതിൽ തനിക്ക് ഒരു വ്യക്തിപരമായ താൽപ്പര്യവും തർക്കിക്കാനില്ലാത്ത, ഫയൽ ചെയ്യുന്ന സ്യൂട്ട്, എതിരാളികളായ ക്ലെയിംകാരിൽ ആർക്കാണ് അത് യഥാർത്ഥത്തിൽ അർഹതയുള്ളതെന്ന് കോടതിയോട് തീരുമാനിക്കാൻ ആവശ്യപ്പെടുന്നത്.',
  'garnishee-order': 'നിർവ്വഹണ നടപടികളിലെ ഉത്തരവ്, ജഡ്ജ്മെന്റ്-ഡെബ്റ്റർക്ക് പണം കടപ്പെട്ടിരിക്കുന്ന, അല്ലെങ്കിൽ അയാളുടേതായ പണം കൈവശം വച്ചിരിക്കുന്ന, ഒരു ബാങ്ക് പോലുള്ള മൂന്നാം കക്ഷിയോട്, ആ തുക ജഡ്ജ്മെന്റ്-ഡെബ്റ്റർക്ക് പകരം നേരിട്ട് ഡിക്രി-ഹോൾഡർക്ക് നൽകാൻ നിർദ്ദേശിക്കുന്നത്.',
  'attachment-before-judgment': 'ഒരു സ്യൂട്ട് ഇപ്പോഴും നിലവിലിരിക്കുമ്പോൾ പ്രതിയുടെ സ്വത്ത് കണ്ടുകെട്ടുന്ന ഉത്തരവ്, ഒടുവിൽ തനിക്കെതിരെ നൽകാവുന്ന ഒരു ഡിക്രിയെ തോൽപ്പിക്കാൻ പ്രതി തന്റെ ആസ്തികൾ ഒഴിവാക്കുകയോ നീക്കം ചെയ്യുകയോ ചെയ്യാൻ സാധ്യതയുണ്ടെന്ന് കോടതിക്ക് ബോധ്യമാകുമ്പോൾ നൽകുന്നത്.',
  'costs': 'കോടതി ഫീ, നിയമ ചെലവുകൾ പോലുള്ള വ്യവഹാര ചെലവുകൾ, ഒരു കക്ഷി മറ്റൊരു കക്ഷിക്ക് നൽകണമെന്ന് കോടതിക്ക് നിർദ്ദേശിക്കാവുന്നത്, സാധാരണയായി ഒരു കേസിലെ അന്തിമ തീരുമാനത്തിന്റെ ഭാഗമായി തോൽവി സംഭവിച്ച കക്ഷിയിൽ നിന്ന് ജയിച്ച കക്ഷിക്ക്.',
  'decree-holder-and-judgment-debtor': 'ഒരു ഡിക്രി-ഹോൾഡർ എന്നത് കോടതി ഒരു ഡിക്രി നൽകിയ, അത് നിർവ്വഹിപ്പിക്കാൻ അർഹതയുള്ള കക്ഷിയാണ്. ഒരു ജഡ്ജ്മെന്റ്-ഡെബ്റ്റർ എന്നത് ഡിക്രി നൽകിയിരിക്കുന്നതിനെതിരെ, സാധാരണയായി പണം നൽകാനോ സ്വത്ത് കൈമാറാനോ ഉള്ള ഫലമായ ബാധ്യത കടപ്പെട്ടിരിക്കുന്ന കക്ഷിയാണ്.',
  'consent-decree': 'ഒരു സ്യൂട്ടിലെ ഇരു കക്ഷികളും സ്വമേധയാ സമ്മതിച്ച ഒരു സെറ്റിൽമെന്റിന്റെ നിബന്ധനകൾ പ്രകാരം കോടതി നൽകുന്ന ഡിക്രി, മെറിറ്റിലുള്ള ഒരു തർക്ക വിചാരണയ്ക്ക് ശേഷമല്ല. ഇത് നൽകിയശേഷം, അടിസ്ഥാന തീരുമാനം തെറ്റാണെന്ന കാരണത്തിൽ ഇത് സാധാരണയായി അപ്പീലിൽ ചോദ്യം ചെയ്യാനാവില്ല, പരിമിതമായ സാഹചര്യങ്ങളിലൊഴികെ.',
  'abatement-of-suit': 'ഒരു സ്യൂട്ടിന്റെ, അല്ലെങ്കിൽ ഒരു പ്രത്യേക കക്ഷിയെ സംബന്ധിച്ച അതിന്റെ ഒരു ഭാഗത്തിന്റെ, സ്വയമേവയുള്ള അവസാനം, ഏറ്റവും സാധാരണയായി ഒരു കക്ഷി മരിക്കുകയും അയാളുടെ നിയമപരമായ അനന്തരാവകാശികളെ നിയമം അനുവദിച്ച സമയത്തിനകം റെക്കോർഡിൽ കൊണ്ടുവരാതിരിക്കുകയും ചെയ്യുന്നതുകൊണ്ട്.',
  'liquidated-damages': 'ഒരു കരാറിലെ കക്ഷികൾ, അതിലൊരാൾ ലംഘിച്ചാൽ നഷ്ടപരിഹാരമായി നൽകുമെന്ന് മുൻകൂട്ടി സമ്മതിക്കുന്ന ഒരു നിശ്ചിത തുക, ലംഘനം സംഭവിച്ചതിന് ശേഷം കോടതി വിലയിരുത്തി കണക്കാക്കേണ്ട അൺലിക്വിഡേറ്റഡ് നഷ്ടപരിഹാരത്തിൽ നിന്ന് വ്യത്യസ്തമായി.',
  'receiver': 'തർക്കത്തിലുള്ള വിഷയമായ സ്വത്ത് താൽക്കാലികമായി കൈവശം വയ്ക്കാനോ കൈകാര്യം ചെയ്യാനോ സംരക്ഷിക്കാനോ കോടതി നിയമിക്കുന്ന വ്യക്തി, കേസ് തീരുമാനിക്കുന്നതിനിടയിൽ അത് പാഴാക്കപ്പെടുകയോ കേടുവരുത്തുകയോ തെറ്റായി കൈകാര്യം ചെയ്യുകയോ ചെയ്യാതിരിക്കാൻ.',

  'original-application': 'ഒരു കടക്കാരൻ കടപ്പെട്ടിരിക്കുന്ന പണം തിരിച്ചുപിടിക്കാൻ ഒരു ബാങ്കോ ധനകാര്യ സ്ഥാപനമോ ഡെറ്റ് റിക്കവറി ട്രിബ്യൂണലിന് (DRT) മുൻപ് ഫയൽ ചെയ്യുന്ന പ്രധാന കേസ് രേഖ, ഒരു സിവിൽ കോടതിയിലെ പ്ലെയിന്റിന് സമാനമായ പങ്ക് വഹിക്കുന്നത്.',
  'securitisation-application': 'SARFAESI ആക്ട് പ്രകാരം ഒരു കടക്കാരന്റെ ഈടാക്കിയ സ്വത്ത് പിടിച്ചെടുക്കാനോ വിൽക്കാനോ ഒരു വായ്പാദാതാവ് സ്വീകരിച്ച നടപടികളെ ചോദ്യം ചെയ്ത്, ഒരു കടക്കാരനോ മറ്റ് ബാധിത വ്യക്തിയോ ഡെറ്റ് റിക്കവറി ട്രിബ്യൂണലിന് മുൻപ് ഫയൽ ചെയ്യുന്ന അപേക്ഷ.',
  'sarfaesi': 'സെക്യൂരിറ്റൈസേഷൻ ആൻഡ് റീകൺസ്ട്രക്ഷൻ ഓഫ് ഫിനാൻഷ്യൽ അസറ്റ്‌സ് ആൻഡ് എൻഫോഴ്‌സ്‌മെന്റ് ഓഫ് സെക്യൂരിറ്റി ഇന്ററസ്റ്റ് ആക്ട്, 2002-ന്റെ ചുരുക്കെഴുത്ത്. കടക്കാരൻ വായ്പ തിരിച്ചടയ്ക്കാതിരിക്കുമ്പോൾ, ഒരു വായ്പയ്ക്ക് ഈടായി വച്ച സ്വത്ത്, ആദ്യം കോടതിയിൽ കേസ് ഫയൽ ചെയ്യാതെ തന്നെ, ബാങ്കുകൾക്കും ചില ധനകാര്യ സ്ഥാപനങ്ങൾക്കും നേരിട്ട് പിടിച്ചെടുക്കാനും വിൽക്കാനും ഇത് അനുവദിക്കുന്നു.',
  'recovery-certificate': 'ഒരു ഒറിജിനൽ അപ്ലിക്കേഷൻ വായ്പാദാതാവിന് അനുകൂലമായി തീരുമാനിച്ച ശേഷം ഡെറ്റ് റിക്കവറി ട്രിബ്യൂണൽ നൽകുന്ന സർട്ടിഫിക്കറ്റ്, കടക്കാരന്റെ സ്വത്ത് കണ്ടുകെട്ടിയും വിറ്റും ഉൾപ്പെടെ, കുടിശ്ശികയായ തുക തിരിച്ചുപിടിക്കാൻ അധികാരം നൽകുന്നത്.',
  'debt-recovery-officer': 'റിക്കവറി സർട്ടിഫിക്കറ്റ് നൽകിയശേഷം, കടക്കാരന്റെ സ്വത്ത് കണ്ടുകെട്ടുകയും വിൽപ്പനയ്ക്ക് വയ്ക്കുകയും പോലുള്ള, യഥാർത്ഥത്തിൽ റിക്കവറി പ്രക്രിയ നടത്തുന്ന ഉത്തരവാദിത്തമുള്ള, ഡെറ്റ് റിക്കവറി ട്രിബ്യൂണലുമായി ബന്ധപ്പെട്ട ഉദ്യോഗസ്ഥൻ.',
  'cirp': 'ഇൻസോൾവൻസി ആൻഡ് ബാങ്ക്‌റപ്‌സി കോഡ് പ്രകാരം നടത്തുന്ന പ്രക്രിയ, അതിൽ കടം തിരിച്ചടയ്ക്കുന്നതിൽ വീഴ്ച വരുത്തിയ ഒരു കമ്പനിയെ, നിയമിക്കപ്പെട്ട ഒരു റെസല്യൂഷൻ പ്രൊഫഷണൽ ഏറ്റെടുക്കുന്നു, അയാൾ കമ്പനിയുടെ കടക്കാരുമായി ചേർന്ന് ഒരു റെസല്യൂഷൻ പ്ലാനിന് കീഴിൽ അതിനെ പുനരുജ്ജീവിപ്പിക്കാനോ ലിക്വിഡേഷനിലേക്ക് നീക്കാനോ ശ്രമിക്കുന്നു.',
  'miscellaneous-application': 'പ്രധാനമായി ഒരു നിലവിലുള്ള കേസുമായി ബന്ധപ്പെട്ട ഒരു പ്രത്യേക നിർദ്ദേശമോ ആശ്വാസമോ തേടി, ഉദാഹരണത്തിന് ഒരു നടപടിക്രമ വ്യക്തത തേടി, NCLT-ക്കോ NCLAT-ക്കോ മുൻപ് ഫയൽ ചെയ്യുന്ന അപേക്ഷ, പൂർണ്ണമായി പുതിയ ഒരു ക്ലെയിം ഉന്നയിക്കുന്നതിന് പകരം.',
  'resolution-plan': 'കോർപ്പറേറ്റ് ഇൻസോൾവൻസി റെസല്യൂഷൻ പ്രോസസിനിടയിൽ, ഒരു സാധ്യതയുള്ള വാങ്ങുന്നയാളോ നിക്ഷേപകനോ സമർപ്പിക്കുന്ന പ്ലാൻ, സാമ്പത്തികമായി തകർന്ന ഒരു കമ്പനി എങ്ങനെ പുനരുജ്ജീവിപ്പിക്കുമെന്നും അതിന്റെ കടക്കാർക്ക് എങ്ങനെ പണം നൽകുമെന്നും നിർദ്ദേശിക്കുന്നത്. ഇതിന് കമ്മിറ്റി ഓഫ് ക്രെഡിറ്റേഴ്‌സിന്റെ അംഗീകാരവും, പിന്നീട് NCLT-യുടെ അംഗീകാരവും ലഭിക്കേണ്ടത്, അത് പ്രാബല്യത്തിൽ വരുന്നതിന് മുൻപ്.',
  'committee-of-creditors': 'കോർപ്പറേറ്റ് ഇൻസോൾവൻസി റെസല്യൂഷൻ പ്രോസസിനിടയിൽ രൂപീകരിക്കുന്ന, പ്രധാനമായും ഒരു കമ്പനിയുടെ ഫിനാൻഷ്യൽ ക്രെഡിറ്റേഴ്‌സ് ഉൾപ്പെടുന്ന സമിതി, ഏത് റെസല്യൂഷൻ പ്ലാൻ അംഗീകരിക്കണം അല്ലെങ്കിൽ കമ്പനി പകരം ലിക്വിഡേറ്റ് ചെയ്യണോ എന്നതുപോലുള്ള പ്രധാന കാര്യങ്ങൾ തീരുമാനിക്കുന്നത്.',
  'operational-creditor': 'സാധനങ്ങൾ വിതരണം ചെയ്തതിനോ സേവനങ്ങൾ നൽകിയതിനോ ഒരു കമ്പനി പണം കടപ്പെട്ടിരിക്കുന്ന ഒരു കടക്കാരൻ, ഉദാഹരണത്തിന് ഒരു വെണ്ടറോ സപ്ലയറോ, കമ്പനി കടം വാങ്ങിയതോ മുൻകൂട്ടി നൽകിയതോ ആയ പണത്തിന് കടപ്പെട്ടിരിക്കുന്ന ഫിനാൻഷ്യൽ ക്രെഡിറ്ററിൽ നിന്ന് വ്യത്യസ്തമായി.',
  'financial-creditor': 'ഒരു ബാങ്ക് ലോണോ ഡിബഞ്ചറുകളോ പോലുള്ള, പണം കടം വാങ്ങിയതിൽ നിന്നോ സമാനമായ ഒരു ധനകാര്യ ക്രമീകരണത്തിൽ നിന്നോ ഉണ്ടാകുന്ന ഒരു കടം ഒരു കമ്പനി കടപ്പെട്ടിരിക്കുന്ന കടക്കാരൻ, സാധനങ്ങൾക്കോ സേവനങ്ങൾക്കോ പണം കടപ്പെട്ടിരിക്കുന്ന ഓപ്പറേഷണൽ ക്രെഡിറ്ററിൽ നിന്ന് വ്യത്യസ്തമായി.',
  'consumer-complaint': 'ഒരു വിൽപ്പനക്കാരന്റെയോ സേവന ദാതാവിന്റെയോ ഭാഗത്തുനിന്ന് സേവനത്തിലെ കുറവോ സാധനങ്ങളിലെ വൈകല്യമോ അന്യായമായ വ്യാപാര രീതിയോ ആരോപിച്ച്, ഒരു ഉപഭോക്താവ് ഉപഭോക്തൃ കമ്മീഷന് മുൻപ് ഫയൽ ചെയ്യുന്ന, നഷ്ടപരിഹാരമോ മറ്റൊരു പരിഹാരമോ ആവശ്യപ്പെടുന്ന രേഖ.',
  'opposite-party': 'ഒരു ഉപഭോക്താവ് ഉപഭോക്തൃ കമ്മീഷന് മുൻപ് പരാതി ഫയൽ ചെയ്തിരിക്കുന്ന വിൽപ്പനക്കാരൻ, നിർമ്മാതാവ്, അല്ലെങ്കിൽ സേവന ദാതാവ്, ഒരു സാധാരണ സിവിൽ കേസിലെ പ്രതിക്ക് തുല്യമായത്.',
  'deficiency-in-service': 'വാഗ്ദാനം ചെയ്തതോ നിയമം ആവശ്യപ്പെടുന്നതോ ആയതുമായി താരതമ്യം ചെയ്യുമ്പോൾ, ഒരു സേവനത്തിന്റെ ഗുണനിലവാരത്തിലോ സ്വഭാവത്തിലോ രീതിയിലോ ഉള്ള ഒരു കുറവ്, അപൂർണ്ണത, അല്ലെങ്കിൽ അപര്യാപ്തത. ഒരു ഉപഭോക്തൃ കമ്മീഷന് മുൻപ് ഒരു ഉപഭോക്താവ് പരാതി ഫയൽ ചെയ്യാവുന്ന പ്രധാന കാരണങ്ങളിൽ ഒന്നാണ് ഇത്.',
  'unfair-trade-practice': 'സാധനങ്ങളോ സേവനങ്ങളോ പ്രോത്സാഹിപ്പിക്കാനോ വിൽക്കാനോ ഒരു വിൽപ്പനക്കാരനോ സേവന ദാതാവോ ഉപയോഗിക്കുന്ന, തെറ്റിദ്ധരിപ്പിക്കുന്നതോ വഞ്ചനാപരമോ ആയ രീതി, ഉദാഹരണത്തിന് തെറ്റായ പരസ്യം ചെയ്യലോ ഒരു ഉൽപ്പന്നത്തിന്റെ ഗുണനിലവാരം തെറ്റായി അവതരിപ്പിക്കലോ. കൂടുതൽ പ്രത്യേക നഷ്ടം സംഭവിച്ചതായി കാണിക്കേണ്ടതില്ലാതെ തന്നെ ഒരു ഉപഭോക്താവ് ഉപഭോക്തൃ കമ്മീഷന് മുൻപ് ഇതിനെക്കുറിച്ച് പരാതിപ്പെടാം.',
  'consumer-commission-hierarchy': 'ഉപഭോക്തൃ പരാതികൾ കേൾക്കുന്ന മൂന്ന് തട്ടുകളുള്ള ഉപഭോക്തൃ കമ്മീഷൻ സംവിധാനം, ക്ലെയിമിന്റെ മൂല്യം അനുസരിച്ച് സംഘടിപ്പിച്ചത്. ഡിസ്ട്രിക്റ്റ് കമ്മീഷനുകൾ ₹50 ലക്ഷം വരെയുള്ള ക്ലെയിമുകൾ കൈകാര്യം ചെയ്യുന്നു, സ്റ്റേറ്റ് കമ്മീഷനുകൾ ₹50 ലക്ഷത്തിനും ₹2 കോടിക്കും ഇടയിലുള്ള ക്ലെയിമുകളും ഡിസ്ട്രിക്റ്റ് കമ്മീഷനുകളിൽ നിന്നുള്ള അപ്പീലുകളും കൈകാര്യം ചെയ്യുന്നു, നാഷണൽ കമ്മീഷൻ ₹2 കോടിക്ക് മുകളിലുള്ള ക്ലെയിമുകളും സ്റ്റേറ്റ് കമ്മീഷനുകളിൽ നിന്നുള്ള അപ്പീലുകളും കൈകാര്യം ചെയ്യുന്നു.',
  'special-leave-petition': 'ഭരണഘടനയുടെ ആർട്ടിക്കിൾ 136 പ്രകാരം, രാജ്യത്തെ ഏതൊരു കോടതിയുടെയോ ട്രിബ്യൂണലിന്റെയോ വിധിക്കോ ഉത്തരവിനോ എതിരെ അപ്പീൽ ചെയ്യാൻ പ്രത്യേക അനുമതി തേടി സുപ്രീം കോടതിയിൽ ഫയൽ ചെയ്യുന്ന ഹർജി. ആദ്യം സുപ്രീം കോടതിയുടെ വിവേചനാധികാര അനുമതി ആവശ്യമായതിനാൽ, സാധാരണയായി ഒരു അവകാശമായ ഒരു സാധാരണ അപ്പീലിൽ നിന്ന് ഇത് വ്യത്യസ്തമായ ഒരു ഘട്ടമാണ്.',
  'debts-recovery-appellate-tribunal': 'ഡെറ്റ് റിക്കവറി ട്രിബ്യൂണൽ (DRT) നൽകിയ ഉത്തരവുകൾക്കെതിരെ, ഉദാഹരണത്തിന് ഒറിജിനൽ അപ്ലിക്കേഷനുകളിലോ സെക്യൂരിറ്റൈസേഷൻ അപ്ലിക്കേഷനുകളിലോ ഉള്ളവ, അപ്പീലുകൾ കേൾക്കുന്ന അപ്പലേറ്റ് ട്രിബ്യൂണൽ.',
  'pre-deposit': 'ഒരു അപ്പീൽ, ഏറ്റവും സാധാരണയായി DRT, NCLT, അല്ലെങ്കിൽ SARFAESI ഉത്തരവിനെതിരെ, രജിസ്റ്റർ ചെയ്യുകയോ കേൾക്കുകയോ ചെയ്യുന്നതിന് മുൻപ്, അപ്പലേറ്റ് ട്രിബ്യൂണലിൽ ഒരു കക്ഷി കെട്ടിവയ്ക്കേണ്ട ഒരു തുക, സാധാരണയായി തർക്കത്തിലുള്ള തുകയുടെ ഒരു ശതമാനമായി നിശ്ചയിച്ചത്.',
  'national-company-law-tribunal': 'കമ്പനി നിയമവും ഇൻസോൾവൻസി വിഷയങ്ങളും തീരുമാനിക്കുന്ന പ്രത്യേക ട്രിബ്യൂണൽ, കമ്പനി തർക്കങ്ങൾ, മെർജറുകൾ, കോർപ്പറേറ്റ് ഇൻസോൾവൻസി റെസല്യൂഷൻ പ്രോസസ് എന്നിവ ഉൾപ്പെടെ.',
  'national-company-law-appellate-tribunal': 'നാഷണൽ കമ്പനി ലോ ട്രിബ്യൂണൽ നൽകിയ ഉത്തരവുകൾക്കെതിരെ അപ്പീലുകൾ കേൾക്കുന്ന അപ്പലേറ്റ് ട്രിബ്യൂണൽ.',
  'corporate-debtor': 'കടം തിരിച്ചടയ്ക്കുന്നതിൽ വീഴ്ച വരുത്തിയതിനാൽ കോർപ്പറേറ്റ് ഇൻസോൾവൻസി റെസല്യൂഷൻ പ്രോസസ് ആരംഭിച്ചിരിക്കുന്ന കമ്പനി.',
  'resolution-professional': 'കോർപ്പറേറ്റ് ഇൻസോൾവൻസി റെസല്യൂഷൻ പ്രോസസിനിടയിൽ ഒരു കമ്പനിയുടെ കാര്യങ്ങൾ നടത്താൻ നിയമിച്ച ഇൻസോൾവൻസി പ്രൊഫഷണൽ, കടക്കാരുടെ ക്ലെയിമുകൾ ക്ഷണിക്കുകയും സ്ഥിരീകരിക്കുകയും ചെയ്യുന്നതും, ഒരു റെസല്യൂഷൻ പ്ലാൻ തയ്യാറാക്കുന്നതിന് മേൽനോട്ടം വഹിക്കുന്നതും ഉൾപ്പെടെ. പ്രോസസിന്റെ ആദ്യ ഭാഗത്ത്, ഈ പങ്ക് താൽക്കാലികമായി വഹിക്കുന്നു.',
  'moratorium-ibc': 'ഒരു കമ്പനിക്കെതിരെ കോർപ്പറേറ്റ് ഇൻസോൾവൻസി റെസല്യൂഷൻ പ്രോസസ് സ്വീകരിച്ചുകഴിഞ്ഞാൽ പ്രാബല്യത്തിൽ വരുന്ന, റിക്കവറി സ്യൂട്ടുകളും സെക്യൂരിറ്റി നിർവ്വഹണവും ഉൾപ്പെടെ മിക്ക നിയമ നടപടികളും ഫയൽ ചെയ്യുന്നതിലോ തുടരുന്നതിലോ ഉള്ള സ്വയമേവയുള്ള മരവിപ്പ്. പ്രോസസ് തുടരുന്നിടത്തോളം ഇത് നിലനിൽക്കും.',
  'liquidator': 'കോർപ്പറേറ്റ് ഇൻസോൾവൻസി റെസല്യൂഷൻ പ്രോസസ് അംഗീകരിച്ച ഒരു റെസല്യൂഷൻ പ്ലാനിലേക്ക് നയിക്കാതിരുന്നതിനെ തുടർന്ന്, ലിക്വിഡേഷനിലേക്ക് ഉത്തരവിട്ടശേഷം, ഒരു കമ്പനിയുടെ ആസ്തികൾ വിറ്റ് അതിന്റെ കടക്കാർക്കിടയിൽ തുക വിതരണം ചെയ്യാൻ നിയമിച്ച ഇൻസോൾവൻസി പ്രൊഫഷണൽ.',
  'possession-notice-sarfaesi': 'ഒരു കടക്കാരൻ വീഴ്ച വരുത്തിയശേഷം, SARFAESI ആക്ട് പ്രകാരം ഒരു ബാങ്കോ ധനകാര്യ സ്ഥാപനമോ നൽകുന്ന നോട്ടീസ്, വായ്പയ്ക്ക് ഈടായി വച്ച സ്വത്തിന്റെ കൈവശം വായ്പാദാതാവ് ഏറ്റെടുത്തെന്ന് അറിയിക്കുന്നത്.',
  'division-bench': 'സിംഗിൾ ജഡ്ജ് ബെഞ്ചിൽ നിന്ന് വേർതിരിച്ച്, രണ്ടോ അതിലധികമോ ജഡ്ജുമാർ ഒന്നിച്ചിരിക്കുന്ന ഹൈക്കോടതിയുടെയോ സുപ്രീം കോടതിയുടെയോ ബെഞ്ച്. ഒരു സിംഗിൾ ജഡ്ജിന്റെ ഉത്തരവിനെതിരെയുള്ള അപ്പീൽ പോലുള്ള ചില വിഷയങ്ങൾ ഡിവിഷൻ ബെഞ്ച് തന്നെ കേൾക്കണമെന്ന് ആവശ്യപ്പെടുന്നു.',
  'adjudicating-authority': 'ഇൻസോൾവൻസി ആൻഡ് ബാങ്ക്‌റപ്‌സി കോഡിന് കീഴിലുള്ള കാര്യങ്ങൾ, ഉദാഹരണത്തിന് കോർപ്പറേറ്റ് ഇൻസോൾവൻസി റെസല്യൂഷൻ പ്രോസസ് ആരംഭിക്കാനുള്ള ഒരു അപേക്ഷ സ്വീകരിക്കൽ അല്ലെങ്കിൽ നിരസിക്കൽ, തീരുമാനിക്കുമ്പോൾ നാഷണൽ കമ്പനി ലോ ട്രിബ്യൂണൽ നിർവ്വഹിക്കുന്ന പങ്ക്.',

  'board-resolution': 'കമ്പനിയുടെ ഡയറക്ടർ ബോർഡ് ശരിയായി വിളിച്ചുകൂട്ടിയ ഒരു മീറ്റിംഗിൽ പാസാക്കുന്ന ഔപചാരികമായ രേഖാമൂലമായ തീരുമാനം, ഒരു ബാങ്ക് അക്കൗണ്ട് തുറക്കുക, ഒരു ഓഫീസറെ നിയമിക്കുക, അല്ലെങ്കിൽ ഒരു ഇടപാട് അംഗീകരിക്കുക പോലുള്ള ഒരു പ്രത്യേക കാര്യത്തിലെ അവരുടെ അംഗീകാരം രേഖപ്പെടുത്തുന്നത്.',
  'memorandum-of-association': 'ഒരു കമ്പനിയുടെ സ്ഥാപനസമയത്ത് ഫയൽ ചെയ്യുന്ന അടിസ്ഥാന രേഖ, അതിന്റെ പേര്, രജിസ്റ്റർ ചെയ്ത ഓഫീസ്, ലക്ഷ്യങ്ങളോ ഉദ്ദേശ്യമോ, അതിന് നടത്താൻ അനുവാദമുള്ള പ്രവർത്തനങ്ങളുടെ പരിധിയും നിർവ്വചിക്കുന്നത്. ഈ രേഖ അനുവദിക്കുന്നതിനപ്പുറം സാധാരണയായി ഒരു കമ്പനിക്ക് പ്രവർത്തിക്കാനാവില്ല.',
  'articles-of-association': 'ഒരു കമ്പനി എങ്ങനെ നടത്തുന്നു എന്ന് നിയന്ത്രിക്കുന്ന ആന്തരിക നിയമങ്ങൾ വ്യക്തമാക്കുന്ന രേഖ, ഷെയർഹോൾഡർമാരുടെ അവകാശങ്ങൾ, ഡയറക്ടർമാരുടെ അധികാരങ്ങൾ, മീറ്റിംഗുകൾ എങ്ങനെ നടത്തുന്നു എന്നതുപോലുള്ള കാര്യങ്ങൾ ഉൾക്കൊള്ളുന്നത്. ഇത് മെമ്മോറാണ്ടം ഓഫ് അസോസിയേഷനോടൊപ്പം പ്രവർത്തിക്കുന്നു, പക്ഷേ കമ്പനിയുടെ ഉദ്ദേശ്യത്തിന് പകരം ആന്തരിക മാനേജ്മെന്റിനെ കൈകാര്യം ചെയ്യുന്നു.',
  'share-transfer-deed': 'ഒരു കമ്പനിയുടെ ഷെയറുകൾ ഒരു ഷെയർഹോൾഡറിൽ നിന്ന് മറ്റൊരാളിലേക്ക് ഔപചാരികമായി കൈമാറാൻ ഉപയോഗിക്കുന്ന നിശ്ചിത ഫോം, ഫോം SH-4. കമ്പനിക്ക് കൈമാറ്റം രജിസ്റ്റർ ചെയ്യുന്നതിന് മുൻപ്, ട്രാൻസ്ഫററും ട്രാൻസ്ഫറിയും ഇത് ശരിയായി സ്റ്റാമ്പ് ചെയ്ത് നിർവ്വഹിക്കണം.',
  'llp-agreement': 'ഒരു ലിമിറ്റഡ് ലയബിലിറ്റി പാർട്ണർഷിപ്പിന്റെ പാർട്ണർമാർക്കിടയിലും, പാർട്ണർമാർക്കും LLP-ക്കും ഇടയിലുമുള്ള കരാർ, ഓരോ പാർട്ണറുടെയും മൂലധന സംഭാവന, ലാഭ-വിഹിത അനുപാതം, മാനേജ്മെന്റ് അവകാശങ്ങളും കടമകളും പോലുള്ള കാര്യങ്ങൾ വ്യക്തമാക്കുന്നത്.',
  'registrar-of-companies': 'മിനിസ്ട്രി ഓഫ് കോർപ്പറേറ്റ് അഫയേഴ്‌സിന് കീഴിൽ പ്രവർത്തിക്കുന്ന, ഒരു പ്രത്യേക സംസ്ഥാനത്തോ പ്രദേശത്തോ കമ്പനികളും LLP-കളും രജിസ്റ്റർ ചെയ്യുന്നതിനും അവയുടെ തുടർച്ചയായ പാലന ഫയലിംഗുകൾക്ക് മേൽനോട്ടം വഹിക്കുന്നതിനും ഉത്തരവാദിയായ സർക്കാർ ഉദ്യോഗസ്ഥൻ.',
  'director-identification-number': 'ഇന്ത്യയിലെ ഒരു കമ്പനിയുടെ ഡയറക്ടറായി നിയമിക്കപ്പെടുന്നതിന് മുൻപ് ഓരോ വ്യക്തിയും നേടേണ്ട അദ്വിതീയ തിരിച്ചറിയൽ നമ്പർ. അയാൾ ഡയറക്ടറായിട്ടുള്ള എല്ലാ കമ്പനികളിലും ഇത് ആ വ്യക്തിക്കൊപ്പം തുടരും.',
  'winding-up': 'ഒരു കമ്പനി അടച്ചുപൂട്ടുന്ന നിയമപ്രക്രിയ, അതിലൂടെ അതിന്റെ ആസ്തികൾ ശേഖരിക്കുകയും, കടങ്ങൾ ഒടുക്കുകയും, ബാക്കിയുള്ളത് ഷെയർഹോൾഡർമാർക്കിടയിൽ വിതരണം ചെയ്യുകയും ചെയ്യുന്നത്, അതിന് ശേഷം കമ്പനി ഒടുവിൽ പിരിച്ചുവിടുകയും രജിസ്റ്ററിൽ നിന്ന് നീക്കം ചെയ്യുകയും ചെയ്യുന്നു.',
  'e-form': 'മിനിസ്ട്രി ഓഫ് കോർപ്പറേറ്റ് അഫയേഴ്‌സിന്റെ ഓൺലൈൻ പോർട്ടൽ വഴി രജിസ്ട്രാർ ഓഫ് കമ്പനീസിൽ ഫയൽ ചെയ്യുന്ന ഇലക്ട്രോണിക് ഫോം, ഒരു ഡയറക്ടറെ നിയമിക്കുക, രജിസ്റ്റർ ചെയ്ത ഓഫീസ് മാറ്റുക, അല്ലെങ്കിൽ വാർഷിക റിട്ടേണുകൾ ഫയൽ ചെയ്യുക പോലുള്ള സ്ഥിരം പാലന ഫയലിംഗുകൾക്ക് ഉപയോഗിക്കുന്നത്.',
  'statutory-register': 'ഒരു കമ്പനി നിയമപരമായി സൂക്ഷിക്കേണ്ട ഒരു റെക്കോർഡ്, അതിന്റെ ഷെയർഹോൾഡർമാരുടെയോ ഡയറക്ടർമാരുടെയോ ആസ്തികളിലെ ചാർജുകളുടെയോ പട്ടിക പോലുള്ള പ്രത്യേക വിവരങ്ങൾ ഉൾക്കൊള്ളുന്നത്. ഈ റെജിസ്റ്ററുകൾ കാലികമായി സൂക്ഷിക്കേണ്ടതും, നിയമം അനുവദിക്കുന്ന സാഹചര്യങ്ങളിൽ പരിശോധനയ്ക്ക് തുറന്നുകൊടുക്കേണ്ടതുമാണ്.',
  'annual-general-meeting': 'മിക്ക കമ്പനികളും ഓരോ ധനകാര്യ വർഷത്തിലും ഒരിക്കൽ നടത്തണമെന്ന് നിയമം ആവശ്യപ്പെടുന്ന മീറ്റിംഗ്, അതിൽ ഷെയർഹോൾഡർമാർ കമ്പനിയുടെ വാർഷിക അക്കൗണ്ടുകൾ അവലോകനം ചെയ്യുകയും, ഡിവിഡന്റുകൾ അംഗീകരിക്കുകയും, ഡയറക്ടർമാരെയും ഓഡിറ്റർമാരെയും നിയമിക്കുക പോലുള്ള കാര്യങ്ങൾ കൈകാര്യം ചെയ്യുകയും ചെയ്യുന്നു.',
  'extraordinary-general-meeting': 'ആന്വൽ ജനറൽ മീറ്റിംഗ് അല്ലാതെ നടത്തുന്ന ഒരു കമ്പനിയുടെ ഷെയർഹോൾഡർമാരുടെ ഏതൊരു മീറ്റിംഗും, അടുത്ത വാർഷിക മീറ്റിംഗിന് വരെ കാത്തിരിക്കാനാവാത്ത അടിയന്തരമോ പ്രത്യേകമോ ആയ കാര്യങ്ങളിൽ തീരുമാനമെടുക്കാൻ വിളിച്ചുകൂട്ടുന്നത്.',
  'authorised-share-capital': 'ഒരു കമ്പനിക്ക് ഷെയർഹോൾഡർമാർക്ക് ഇഷ്യൂ ചെയ്യാൻ അനുവാദമുള്ള ഷെയറുകളുടെ പരമാവധി മൂല്യം, അതിന്റെ മെമ്മോറാണ്ടം ഓഫ് അസോസിയേഷനിൽ പ്രസ്താവിച്ചിരിക്കുന്നത്. ഈ പരിധിക്ക് മുകളിൽ ഷെയറുകൾ ഇഷ്യൂ ചെയ്യുന്നതിന് മുൻപ് കമ്പനി ഔപചാരികമായി ഈ പരിധി ഉയർത്തണം.',
  'paid-up-share-capital': 'ഇതുവരെ തങ്ങൾക്ക് ഇഷ്യൂ ചെയ്ത ഷെയറുകൾക്ക് പകരമായി ഷെയർഹോൾഡർമാർ കമ്പനിക്ക് യഥാർത്ഥത്തിൽ നൽകിയ തുക. ഇത് വെറും ഇഷ്യൂ ചെയ്യാൻ അനുവാദമുള്ള മേൽപരിധിയായ ഓതറൈസ്ഡ് ഷെയർ ക്യാപിറ്റലിനേക്കാൾ കുറവായിരിക്കാം.',
  'certificate-of-incorporation': 'ഒരു കമ്പനി നിയമപരമായി രൂപീകരിക്കുകയും രജിസ്റ്റർ ചെയ്യുകയും ചെയ്തെന്ന് സ്ഥിരീകരിച്ച്, രജിസ്ട്രാർ ഓഫ് കമ്പനീസ് നൽകുന്ന ഔദ്യോഗിക സർട്ടിഫിക്കറ്റ്. ഈ സർട്ടിഫിക്കറ്റിലെ തീയതി മുതൽ, അതിന്റെ സ്ഥാപകരിൽ നിന്ന് വേറിട്ട ഒരു സ്ഥാപനമായി കമ്പനി നിയമപരമായി നിലവിൽ വരുന്നു.',
  'registered-office': 'രജിസ്ട്രാർ ഓഫ് കമ്പനീസിൽ രേഖപ്പെടുത്തിയ കമ്പനിയുടെ ഔദ്യോഗിക വിലാസം, നിയമപരമായ നോട്ടീസുകളും ഔദ്യോഗിക ആശയവിനിമയങ്ങളും സ്വീകരിക്കാൻ ഉപയോഗിക്കുന്നത്. ഇത് കമ്പനിയുടെ പ്രധാന ബിസിനസ്സ് സ്ഥലം ആവശ്യമില്ല, പക്ഷേ അവിടെ ആശയവിനിമയങ്ങൾ സ്വീകരിക്കാൻ കമ്പനിക്ക് കഴിയണം.',
  'scheme-of-arrangement': 'ഒരു മെർജർ, ഡിമെർജർ, അല്ലെങ്കിൽ കടങ്ങളിലെ ഒത്തുതീർപ്പ് പോലുള്ള ആവശ്യങ്ങൾക്ക് ഉപയോഗിക്കുന്ന, ഒരു കമ്പനിക്കും അതിന്റെ ഷെയർഹോൾഡർമാർക്കോ കടക്കാർക്കോ ഇടയിലുള്ള ഒരു ക്രമീകരണം, നാഷണൽ കമ്പനി ലോ ട്രിബ്യൂണൽ അംഗീകരിച്ചശേഷം എല്ലാ കക്ഷികൾക്കും ബന്ധനമാകുന്നത്.',
  'private-company': 'തങ്ങളുടെ ഷെയറുകൾ പൊതുജനങ്ങൾക്ക് സ്വതന്ത്രമായി നൽകാനാവാത്ത, അതിന്റെ ആർട്ടിക്കിൾസ് ഷെയറുകൾ കൈമാറാനുള്ള അവകാശം പരിമിതപ്പെടുത്തുന്ന കമ്പനി, സ്വതന്ത്രമായി വ്യാപാരം ചെയ്യാവുന്നതും, ലിസ്റ്റ് ചെയ്തെങ്കിൽ ഒരു സ്റ്റോക്ക് എക്സ്ചേഞ്ചിൽ വാങ്ങുകയും വിൽക്കുകയും ചെയ്യാവുന്നതുമായ പബ്ലിക് കമ്പനിയിൽ നിന്ന് വേർതിരിച്ച്.',
  'one-person-company': 'ഒരു വ്യക്തിക്ക് മാത്രം രൂപീകരിക്കാനും നടത്താനും കഴിയുന്ന ഒരു തരം കമ്പനി, അയാൾ തന്നെ അതിന്റെ ഒരേയൊരു ഷെയർഹോൾഡർ, അതേസമയം പരിമിതമായ ബാധ്യതയുള്ള ഒരു വേറിട്ട നിയമ സ്ഥാപനമായിരിക്കുന്നതിന്റെ പ്രയോജനം ബിസിനസ്സിന് ഇപ്പോഴും ലഭിക്കുന്നു.',
  'shareholder': 'ഒരു കമ്പനിയിൽ ഷെയറുകൾ കൈവശമുള്ള, അതിന് ആ അളവിൽ അതിന്റെ ഒരു ഉടമയായ വ്യക്തി, ജനറൽ മീറ്റിംഗുകളിൽ വോട്ട് ചെയ്യുക, ഡിവിഡന്റ് സ്വീകരിക്കുക പോലുള്ള അവകാശങ്ങളോടെ. കമ്പനിയുടെ അംഗം എന്നും വിളിക്കുന്നു.',
  'director': 'കമ്പനിയുടെ കാര്യങ്ങൾ നടത്താനും അതിന് വേണ്ടി തീരുമാനങ്ങൾ എടുക്കാനും ബോർഡിലേക്ക് നിയമിക്കപ്പെടുന്ന വ്യക്തി, നല്ല വിശ്വാസത്തോടെയും കമ്പനിയുടെ നല്ലതിനായും പ്രവർത്തിക്കാനുള്ള കടമകളോടെ. ഒരു മാനേജിംഗ് ഡയറക്ടറോ വേറെ മുഴുവൻ സമയ ഡയറക്ടറോ, വെറും ബോർഡ് മീറ്റിംഗുകളിൽ പങ്കെടുക്കുന്നതിനപ്പുറം, പ്രത്യേക ദൈനംദിന എക്സിക്യൂട്ടീവ് ഉത്തരവാദിത്തങ്ങൾ നൽകപ്പെട്ടയാളാണ്.',
  'company-secretary': 'സ്റ്റാറ്റ്യൂട്ടറി രജിസ്റ്ററുകൾ സൂക്ഷിക്കുക, മീറ്റിംഗുകൾ സംഘടിപ്പിക്കുക, രജിസ്ട്രാർ ഓഫ് കമ്പനീസിൽ സമയത്തിന് ഫയലിംഗുകൾ നടത്തുന്നുവെന്ന് ഉറപ്പാക്കുക എന്നിവ ഉൾപ്പെടെ, കമ്പനി നിയമ പാലനത്തിന് ഉത്തരവാദിയായ ഒരു യോഗ്യതയുള്ള പ്രൊഫഷണൽ.',
  'auditor': 'ഒരു കമ്പനിയുടെ സാമ്പത്തിക പ്രസ്താവനകളും അക്കൗണ്ടിംഗ് റെക്കോർഡുകളും പരിശോധിക്കാനും, അവ കമ്പനിയുടെ സാമ്പത്തിക സ്ഥിതിയുടെ ശരിയായതും ന്യായവുമായ ഒരു ചിത്രം നൽകുന്നോ എന്ന് ഷെയർഹോൾഡർമാരോട് റിപ്പോർട്ട് ചെയ്യാനും ഒരു കമ്പനി നിയമിക്കുന്ന സ്വതന്ത്രവും യോഗ്യതയുള്ളതുമായ പ്രൊഫഷണൽ.',
  'charge-company': 'ഒരു വായ്പയ്ക്ക് ഈടായി, ഒരു വായ്പാദാതാവിന് അനുകൂലമായി, ഒരു കമ്പനിയുടെ ആസ്തികളിൽ, ഉദാഹരണത്തിന് അതിന്റെ സ്വത്തിലോ സ്വീകരിക്കേണ്ട പണത്തിലോ, സൃഷ്ടിക്കുന്ന ഒരു അവകാശം. മറ്റുള്ളവർക്കെതിരെ ഇത് നിലവിൽ വരുത്താൻ, ഒരു നിശ്ചിത സമയത്തിനകം ഈ ചാർജ് രജിസ്ട്രാർ ഓഫ് കമ്പനീസിൽ രജിസ്റ്റർ ചെയ്യണം.',
  'dividend': 'ഒരു ജനറൽ മീറ്റിംഗിൽ പ്രഖ്യാപിച്ചശേഷം, അല്ലെങ്കിൽ ഒരു ഇടക്കാല ഡിവിഡന്റിന്റെ കാര്യത്തിൽ ബോർഡ് വഴി, സാധാരണയായി തങ്ങൾ കൈവശം വച്ചിരിക്കുന്ന ഷെയറുകൾക്ക് ആനുപാതികമായി ഷെയർഹോൾഡർമാർക്ക് ഒരു കമ്പനി വിതരണം ചെയ്യുന്ന ലാഭത്തിന്റെ ഒരു ഭാഗം.',
  'quorum': 'ഒരു ബോർഡ് മീറ്റിംഗ്, ആന്വൽ ജനറൽ മീറ്റിംഗ്, അല്ലെങ്കിൽ എക്സ്ട്രാഓർഡിനറി ജനറൽ മീറ്റിംഗ് പോലുള്ള ഒരു മീറ്റിംഗ് സാധുവായി നടത്താനും അതിന്റെ തീരുമാനങ്ങൾ ബന്ധനമാകാനും ഹാജരാകേണ്ട കുറഞ്ഞ അംഗങ്ങളുടെയോ ഡയറക്ടർമാരുടെയോ എണ്ണം.',
  'proxy': 'ഒരു ഷെയർഹോൾഡർക്ക് സ്വയം ഹാജരാകാൻ കഴിയാത്തപ്പോൾ, ഒരു ജനറൽ മീറ്റിംഗിൽ ഹാജരാകാനും അവർക്ക് വേണ്ടി വോട്ട് ചെയ്യാനും, ഒപ്പിട്ട ഒരു രേഖ വഴി, ഷെയർഹോൾഡർ അധികാരപ്പെടുത്തുന്ന വ്യക്തി.',
  'striking-off': 'ഒരു നിർജ്ജീവ കമ്പനിയുടെ പേര്, ഒന്നുകിൽ ഫാസ്റ്റ്-ട്രാക്ക് എക്സിറ്റിനായി കമ്പനിയുടെ സ്വന്തം അപേക്ഷയിലോ, ബിസിനസ്സ് നടത്താത്തപ്പോൾ രജിസ്ട്രാറുടെ തന്നെ മുൻകൈയിലോ, രജിസ്റ്ററിൽ നിന്ന് നീക്കം ചെയ്യുന്ന രജിസ്ട്രാർ ഓഫ് കമ്പനീസിന്റെ പ്രക്രിയ.',
  'oppression-and-mismanagement': 'ഒരു കമ്പനിയുടെ കാര്യങ്ങൾ തങ്ങൾക്ക് മർദ്ദകമോ കമ്പനിയുടെ തന്നെ താൽപ്പര്യത്തിന് ഹാനികരമോ ആയ രീതിയിൽ നടത്തുന്നിടത്ത്, പ്രധാനമായും ന്യൂനപക്ഷ ഷെയർഹോൾഡർമാരായ ഷെയർഹോൾഡർമാർക്ക്, നാഷണൽ കമ്പനി ലോ ട്രിബ്യൂണലിനെ സമീപിക്കാൻ ലഭ്യമായ ഒരു പരിഹാരം.',
  'shareholders-agreement': 'ഒരു കമ്പനിയുടെ ചില അല്ലെങ്കിൽ എല്ലാ ഷെയർഹോൾഡർമാർക്കുമിടയിലുള്ള ഒരു സ്വകാര്യ കരാർ, ഷെയറുകൾ എങ്ങനെ കൈമാറാം, ഡയറക്ടർമാരെ നിയമിക്കാനുള്ള അവകാശങ്ങൾ, ഒരു ഡെഡ്‌ലോക്ക് ഉണ്ടായാൽ എന്ത് സംഭവിക്കും എന്നതുപോലുള്ള കാര്യങ്ങൾ വ്യക്തമാക്കുന്നത്, ആർട്ടിക്കിൾസ് ഓഫ് അസോസിയേഷനിൽ രേഖപ്പെടുത്തിയതിനും അപ്പുറം പോകുന്നത്.',

  'sale-deed': 'ഒരു വിൽപ്പനക്കാരനിൽ നിന്ന് ഒരു വാങ്ങുന്നയാളിലേക്ക്, ഒരു വിലയ്ക്ക് പകരമായി, ഒരു സ്ഥാവര സ്വത്തിന്റെ ഉടമസ്ഥാവകാശം ഔപചാരികമായി കൈമാറുന്ന നിയമ രേഖ. ടൈറ്റിൽ കൈമാറുന്നതിൽ നിയമപരമായി സാധുവാകാൻ ഇത് ശരിയായി സ്റ്റാമ്പ് ചെയ്യുകയും രജിസ്റ്റർ ചെയ്യുകയും വേണം.',
  'gift-deed': 'ഒരു വ്യക്തിയിൽ നിന്ന് മറ്റൊരാളിലേക്ക്, സ്വമേധയാ, പകരം ഒന്നും സ്വീകരിക്കാതെ, ഒരു സ്വത്തിന്റെ ഉടമസ്ഥാവകാശം കൈമാറുന്ന നിയമ രേഖ. ഒരു സെയിൽ ഡീഡ് പോലെ, നിയമപരമായി പ്രാബല്യത്തിൽ വരാൻ ഇതും ശരിയായി സ്റ്റാമ്പ് ചെയ്യുകയും രജിസ്റ്റർ ചെയ്യുകയും വേണം.',
  'lease-deed': 'വാടകയ്ക്ക് പകരമായി, സ്വത്തിന്റെ ഉടമസ്ഥാവകാശം കൈമാറാതെ, ഒരു നിശ്ചിത കാലയളവിലേക്ക് മറ്റൊരാളുടെ സ്വത്ത് കൈവശം വയ്ക്കാനും ഉപയോഗിക്കാനുമുള്ള അവകാശം ഒരാൾക്ക് നൽകുന്ന നിയമ രേഖ.',
  'mortgage-deed': 'ഒരു വായ്പയ്ക്കോ മറ്റൊരു കടത്തിനോ ഈടായി, ഒരു സ്വത്ത് ഉടമ തന്റെ സ്വത്ത് പണയം വയ്ക്കുന്ന നിയമ രേഖ, കടം തിരിച്ചടച്ചില്ലെങ്കിൽ ആ സ്വത്തിൽ വായ്പാദാതാവിന് ചില അവകാശങ്ങൾ നൽകുന്നത്, അനിവാര്യമായി കൈവശം വിട്ടുകൊടുക്കാതെ തന്നെ.',
  'general-power-of-attorney': 'സ്വത്ത് കൈകാര്യം ചെയ്യുക, ബാങ്ക് അക്കൗണ്ടുകൾ നടത്തുക, നിയമകാര്യങ്ങൾ കൈകാര്യം ചെയ്യുക പോലുള്ള വിപുലമായ കാര്യങ്ങളിൽ ഒരാൾക്ക് വേണ്ടി പ്രവർത്തിക്കാൻ മറ്റൊരാളെ അധികാരപ്പെടുത്തുന്ന രേഖ, ഒരു പ്രത്യേക ജോലിയിൽ പരിമിതപ്പെടുന്നതിന് പകരം.',
  'special-power-of-attorney': 'ഒരു പ്രത്യേക സ്വത്ത് വിൽക്കുന്നത് പോലുള്ള, ഒരു പ്രത്യേക ജോലിക്കോ ഇടപാടിനോ മാത്രം, പൊതുവായ കാര്യങ്ങൾക്ക് പകരം, ഒരാൾക്ക് വേണ്ടി പ്രവർത്തിക്കാൻ മറ്റൊരാളെ അധികാരപ്പെടുത്തുന്ന രേഖ.',
  'stamp-duty': 'ഒരു സെയിൽ ഡീഡോ ലീസ് ഡീഡോ പോലുള്ള ചില രേഖകൾ നിർവ്വഹിക്കുമ്പോൾ സംസ്ഥാന സർക്കാരിന് നൽകേണ്ട നികുതി, സാധാരണയായി സ്വത്തിന്റെ മൂല്യത്തിന്റെയോ ഇടപാട് തുകയുടെയോ ഒരു ശതമാനം. ശരിയായ സ്റ്റാമ്പ് ഡ്യൂട്ടി അടയ്ക്കാതെ, ഇത്തരം രേഖകൾ സാധാരണയായി കോടതിയിൽ സാധുവായ തെളിവായി ഉപയോഗിക്കാനോ രജിസ്റ്റർ ചെയ്യാനോ കഴിയില്ല.',
  'registration-of-document': 'സെയിൽ ഡീഡ് അല്ലെങ്കിൽ ഗിഫ്റ്റ് ഡീഡ് പോലുള്ള ഒരു രേഖ, സർക്കാരിന്റെ സബ്-രജിസ്ട്രാർ ഓഫീസിൽ രേഖപ്പെടുത്തുന്ന ഔപചാരിക പ്രക്രിയ. രജിസ്ട്രേഷൻ ഇടപാടിന്റെ ഒരു പൊതു റെക്കോർഡ് സൃഷ്ടിക്കുന്നു, കൂടാതെ പല തരം സ്വത്ത് രേഖകൾക്കും, കൈമാറ്റം സാധുവാക്കാൻ നിയമപരമായി ഇത് ആവശ്യമാണ്.',
  'encumbrance': 'ഒടുക്കാത്ത ഒരു മോർട്ഗേജോ നിലവിലുള്ള ഒരു നിയമ തർക്കമോ പോലുള്ള, ഒരു സ്വത്തിനോട് ചേർന്നിരിക്കുന്ന ഒരു ക്ലെയിം, ബാധ്യത, അല്ലെങ്കിൽ നിയന്ത്രണം, അത് സ്വതന്ത്രമായി വിൽക്കാനോ കൈമാറ്റം ചെയ്യാനോ ഉള്ള ഉടമയുടെ കഴിവിനെ ബാധിക്കാവുന്നത്.',
  'title-deed': 'ഒരു വ്യക്തിയുടെ സ്വത്തിന്റെ ഉടമസ്ഥാവകാശത്തിന് നിയമപരമായ തെളിവായി നിലകൊള്ളുന്ന രേഖ, ഉദാഹരണത്തിന് അയാളുടെ പേരിലുള്ള ഒരു സെയിൽ ഡീഡോ ഗിഫ്റ്റ് ഡീഡോ. ഒരു സ്വത്ത് ഉൾപ്പെടുന്ന ഇടപാടിന് മുൻപ്, അതിന്റെ ഉടമ ആരാണെന്ന് സ്ഥിരീകരിക്കാൻ ഇത് പരിശോധിക്കുന്നു.',
  'consideration-in-a-deed': 'ഒരു ഡീഡിന് കീഴിൽ കൈമാറ്റം ചെയ്യുന്ന ഒരു സ്വത്തിനോ അവകാശത്തിനോ പകരമായി കൈമാറ്റം ചെയ്യുന്ന വില, പേയ്‌മെന്റ്, അല്ലെങ്കിൽ പ്രയോജനം, ഉദാഹരണത്തിന് ഒരു സ്വത്തിന് നൽകിയ വിൽപ്പന വില. ഒരു ഡീഡ് ഉൾപ്പെട്ടിരിക്കുന്ന കൺസിഡറേഷൻ വ്യക്തമായി പ്രസ്താവിക്കണം, അല്ലെങ്കിൽ, ഒരു ഗിഫ്റ്റ് ഡീഡിന്റെ കാര്യത്തിൽ, ഒരു കൺസിഡറേഷനും നൽകിയിട്ടില്ലെന്ന് വ്യക്തമായി പ്രസ്താവിക്കണം.',
  'encumbrance-certificate': 'ഒരു നിശ്ചിത കാലയളവിൽ, ഒരു സ്വത്തിന് മോർട്ഗേജുകളോ ഒടുക്കാത്ത ബാധ്യതകളോ പോലുള്ള ഏതെങ്കിലും രേഖപ്പെടുത്തിയ എൻകംബ്രൻസുകൾ ഉണ്ടോ എന്ന് സ്ഥിരീകരിച്ച്, സബ്-രജിസ്ട്രാർ ഓഫീസ് നൽകുന്ന ഔദ്യോഗിക സർട്ടിഫിക്കറ്റ്. വിൽപ്പനക്കാരന് വ്യക്തവും വിൽക്കാവുന്നതുമായ ടൈറ്റിൽ ഉണ്ടെന്ന് സ്ഥിരീകരിക്കാൻ, സ്വത്ത് വാങ്ങുന്നതിന് മുൻപ് സാധാരണയായി ഇത് പരിശോധിക്കുന്നു.',
  'mutation-of-property': 'ഒരു വിൽപ്പനയ്ക്കോ അനന്തരാവകാശത്തിനോ ശേഷം, ഒരു സ്വത്തിന്റെ ഉടമസ്ഥാവകാശത്തിലെ മാറ്റം പ്രതിഫലിപ്പിക്കാൻ സർക്കാർ റവന്യൂ റെക്കോർഡുകൾ അപ്ഡേറ്റ് ചെയ്യുന്ന പ്രക്രിയ. മ്യൂട്ടേഷൻ തന്നെ ഉടമസ്ഥാവകാശം കൈമാറുന്നില്ല, അത് സെയിൽ ഡീഡ് വഴിയോ മറ്റ് രേഖ വഴിയോ ആണ് സംഭവിക്കുന്നത്, പക്ഷേ പ്രോപ്പർട്ടി ടാക്സ് പോലുള്ള ആവശ്യങ്ങൾക്ക് ഔദ്യോഗിക ഭൂ രേഖകൾ കാലികമായി സൂക്ഷിക്കുന്നു.',
  'easement': 'ഒരു സ്വത്തിന്റെ ഉടമയ്ക്ക്, ഒരു പരിമിതമായ ഉദ്ദേശ്യത്തിന്, അടുത്തുള്ള മറ്റൊരാളുടെ സ്വത്ത് ഉപയോഗിക്കാനുള്ള അവകാശം, ഉദാഹരണത്തിന് ഒരു റോഡിലേക്ക് പ്രവേശിക്കാനുള്ള ഒരു വഴിയവകാശം, അല്ലെങ്കിൽ വെളിച്ചമോ വായുവോ ലഭിക്കാനുള്ള അവകാശം.',
  'lien': 'മറ്റൊരാളുടെ സ്വത്ത് കൈവശം വച്ചിരിക്കുന്ന, അല്ലെങ്കിൽ അതുമായി ബന്ധപ്പെട്ട് പണം ലഭിക്കേണ്ട ഒരാൾക്ക്, കടമോ ക്ലെയിമോ തീർപ്പാകുന്നതുവരെ ആ സ്വത്ത് കൈവശം തുടരാനുള്ള അവകാശം.',
  'conveyance': 'ഒരു വ്യക്തിയിൽ നിന്ന് മറ്റൊരാളിലേക്ക് സ്വത്തിന്റെ ഉടമസ്ഥാവകാശം കൈമാറുന്നതിനുള്ള പൊതുവായ നിയമ പദം, ആ കൈമാറ്റം നടത്തുന്ന സെയിൽ ഡീഡ് പോലുള്ള രേഖയ്ക്കും ഇത് ഉപയോഗിക്കുന്നു.',
  'relinquishment-deed': 'ഒരു സ്വത്തിന്റെ സഹ ഉടമ, ഒന്നോ അതിലധികമോ മറ്റ് സഹ ഉടമകൾക്ക് അനുകൂലമായി, അതിലെ തന്റെ ഓഹരി ഉപേക്ഷിക്കുന്ന രേഖ, ഏറ്റവും സാധാരണയായി ബന്ധുക്കൾക്കിടയിൽ അനന്തരാവകാശമായി ലഭിച്ച കുടുംബ സ്വത്ത് തീർപ്പാക്കാൻ ഉപയോഗിക്കുന്നത്.',
  'will': 'ഒരു വ്യക്തി തന്റെ മരണത്തിന് ശേഷം സ്വത്ത് എങ്ങനെ വിതരണം ചെയ്യണമെന്ന് വ്യക്തമാക്കുന്ന നിയമ രേഖ. ഇത് സാധാരണയായി നിർമ്മിച്ച വ്യക്തിയുടെ മരണത്തിൽ മാത്രം പ്രാബല്യത്തിൽ വരുന്നു, അതിന് മുൻപ് എപ്പോൾ വേണമെങ്കിലും അവർക്ക് ഇത് മാറ്റാനോ റദ്ദാക്കാനോ കഴിയും.',
  'probate': 'ഒരു വിൽ യഥാർത്ഥവും സാധുവുമാണെന്ന് സ്ഥിരീകരിച്ച്, അതിൽ പേരെടുത്ത് പറഞ്ഞ എക്സിക്യൂട്ടർക്ക് മരിച്ച വ്യക്തിയുടെ സ്വത്ത് അതനുസരിച്ച് നടത്താൻ അധികാരം നൽകി, ഒരു യോഗ്യതയുള്ള കോടതി നൽകുന്ന സർട്ടിഫിക്കറ്റ്.',
  'succession-certificate': 'ഒരാൾ വിൽ ഇല്ലാതെ മരിച്ചിടത്ത്, മരിച്ച വ്യക്തിക്ക് ലഭിക്കേണ്ട ബാങ്ക് ബാലൻസുകളോ ഷെയറുകളോ പോലുള്ള കടങ്ങളും സെക്യൂരിറ്റികളും ശേഖരിക്കാനും, അവയ്ക്ക് സാധുവായ ഒരു രസീത് നൽകാനോ കൈമാറ്റം ചെയ്യാനോ, ഹോൾഡർക്ക് അധികാരം നൽകി കോടതി നൽകുന്ന സർട്ടിഫിക്കറ്റ്.',
  'letters-of-administration': 'ഒരാൾ വിൽ ഇല്ലാതെയോ എക്സിക്യൂട്ടറെ പേരെടുത്ത് പറയാതെയോ മരിച്ചിടത്ത്, മരിച്ച വ്യക്തിയുടെ സ്വത്ത് ശേഖരിക്കാനും കൈകാര്യം ചെയ്യാനും വിതരണം ചെയ്യാനും ഒരു അഡ്മിനിസ്ട്രേറ്ററെ നിയമിച്ച്, കോടതി നൽകുന്ന അധികാരപ്പെടുത്തൽ.',
  'legal-heir-certificate': 'ഒരു മരിച്ച വ്യക്തിയുടെ നിയമപരമായ അനന്തരാവകാശികളെ തിരിച്ചറിയുന്ന, റവന്യൂ അല്ലെങ്കിൽ മുനിസിപ്പൽ അധികാരി നൽകുന്ന സർട്ടിഫിക്കറ്റ്, യൂട്ടിലിറ്റി കണക്ഷനുകൾ കൈമാറുക അല്ലെങ്കിൽ ചെറിയ കുടിശ്ശിക ക്ലെയിം ചെയ്യുക പോലുള്ള ലളിതമായ ആവശ്യങ്ങൾക്ക് സാധാരണയായി ഉപയോഗിക്കുന്നത്, വലിയതോ തർക്കത്തിലുള്ളതോ ആയ ക്ലെയിമുകൾക്കുള്ള സക്സഷൻ സർട്ടിഫിക്കറ്റിന് വേഗത്തിലുള്ള ഒരു ബദലായി.',
  'khata-patta': 'ഒരു പ്രത്യേക സ്വത്തിനെതിരെ ഒരു വ്യക്തിയുടെ പേര് കാണിക്കുന്ന, വിവിധ സംസ്ഥാനങ്ങളിൽ ഖാത്ത അല്ലെങ്കിൽ പട്ട എന്ന് വിവിധ പേരുകളിൽ അറിയപ്പെടുന്ന, പ്രോപ്പർട്ടി ടാക്സ് വിലയിരുത്തൽ പോലുള്ള ആവശ്യങ്ങൾക്ക്, പ്രാദേശിക മുനിസിപ്പൽ അല്ലെങ്കിൽ റവന്യൂ അധികാരി സൂക്ഷിക്കുന്ന റെക്കോർഡ്. ഇത് കൈവശമോ നികുതി ബാധ്യതയോ ഈ അധികാരികൾ തന്നെ അംഗീകരിച്ചതിന്റെ ഒരു റെക്കോർഡ് മാത്രമാണ്, അത് ഉടമസ്ഥാവകാശത്തിന് തന്നെ തെളിവല്ല.',
  'adverse-possession': 'യഥാർത്ഥ ഉടമയുടെ അനുമതിയില്ലാതെ, മറ്റൊരാളുടെ സ്വത്തിൽ തുറന്നതും തുടർച്ചയായതും ശത്രുതാപരവുമായ കൈവശം ദീർഘകാലം വഹിച്ച ഒരു വ്യക്തിക്ക്, അതിന്റെ നിയമപരമായ ടൈറ്റിൽ നേടാനും യഥാർത്ഥ ഉടമയുടെ ക്ലെയിം തോൽപ്പിക്കാനും കഴിയുന്ന നിയമപരമായ തത്വം.',
  'benami-transaction': 'ഒരു വ്യക്തിയുടെ പേരിൽ സ്വത്ത് വാങ്ങുന്ന, പക്ഷേ അതിനുള്ള പണം യഥാർത്ഥത്തിൽ അതിന്റെ പ്രയോജനം അനുഭവിക്കുന്ന മറ്റൊരാൾ നൽകുന്ന ഇടപാട്, രേഖകളിൽ പേരെടുത്ത് പറഞ്ഞ വ്യക്തി യഥാർത്ഥ വാങ്ങുന്നയാൾക്കായി മാത്രം അത് കൈവശം വയ്ക്കുന്നത്. ഇത്തരം ഇടപാടുകൾ സാധാരണയായി നിരോധിച്ചിരിക്കുന്നതും, നിയമം അംഗീകരിച്ച പരിമിതമായ ഇളവുകൾക്ക് വിധേയമായി സ്വത്ത് സർക്കാരിന് കണ്ടുകെട്ടാവുന്നതുമാണ്.',
  'landlord-and-tenant': 'ഒരു ലാൻഡ്‌ലോർഡ് എന്നത് ഒരു സ്വത്തിന്റെ ഉടമയാണ്, അയാൾ മറ്റൊരു വ്യക്തിയെ, ടെനന്റിനെ, ഉടമസ്ഥാവകാശം കൈമാറാതെ, ഒരു ലീസ് അല്ലെങ്കിൽ റെന്റൽ കരാറിന് കീഴിൽ, ഒരു നിശ്ചിത കാലയളവിലേക്ക് വാടകയ്ക്ക് പകരമായി അത് കൈവശം വയ്ക്കാനും ഉപയോഗിക്കാനും അനുവദിക്കുന്നു.',
  'mortgagor-and-mortgagee': 'മോർട്ഗേജർ എന്നത് ഒരു മോർട്ഗേജ് ഡീഡിന് കീഴിൽ ഒരു വായ്പയ്ക്ക് ഈടായി തന്റെ സ്വത്ത് പണയം വയ്ക്കുന്ന ഉടമയാണ്. മോർട്ഗേജി എന്നത് ആ ഈട് അനുകൂലമായി സൃഷ്ടിച്ച വായ്പാദാതാവാണ്, മോർട്ഗേജർ വായ്പ തിരിച്ചടയ്ക്കുന്നതിൽ പരാജയപ്പെട്ടാൽ സ്വത്തിൽ തന്റെ അവകാശങ്ങൾ നിലവിൽ വരുത്താൻ കഴിയുന്നയാൾ.',
  'attestation': 'ഒരു വിൽ അല്ലെങ്കിൽ ചില ഡീഡുകൾ പോലുള്ള ഒരു രേഖയിൽ, വ്യക്തി അത് നിർവ്വഹിക്കുന്നത് കണ്ടെന്നും ഒപ്പ് യഥാർത്ഥമാണെന്നും സ്ഥിരീകരിക്കുന്ന സാക്ഷികൾ ഒപ്പിടുന്നത്. ആവശ്യമായ എണ്ണം സാക്ഷികൾ അറ്റസ്റ്റ് ചെയ്താൽ മാത്രമേ ചില രേഖകൾ നിയമപരമായി സാധുവാകുകയുള്ളൂ.',
  'circle-rate': 'ഒരു പ്രത്യേക പ്രദേശത്തെ ഒരു സ്വത്തിന്, സംസ്ഥാന സർക്കാർ വിജ്ഞാപനം ചെയ്യുന്ന, ഔദ്യോഗികമായി ഏറ്റവും കുറഞ്ഞതായി കരുതുന്ന യൂണിറ്റ് വിസ്തൃതിയിലെ മൂല്യം, കക്ഷികൾ തമ്മിൽ സമ്മതിച്ച യഥാർത്ഥ വിൽപ്പന വില കുറവാണെങ്കിലും, സ്റ്റാമ്പ് ഡ്യൂട്ടി കണക്കാക്കുന്നതിനുള്ള ഏറ്റവും കുറഞ്ഞ നിരക്കായി ഉപയോഗിക്കുന്നത്.',

  'res-judicata': 'ഒരു വിഷയം, യോഗ്യതയുള്ള ഒരു കോടതി അതേ കക്ഷികൾക്കിടയിൽ ഇതിനകം അന്തിമമായി തീരുമാനിച്ചുകഴിഞ്ഞാൽ, വീണ്ടും വ്യവഹാരം ചെയ്യുന്നതിൽ നിന്ന് തടയുന്ന നിയമം. ഇതിനകം അന്തിമമായി തീർപ്പാക്കിയ വിഷയങ്ങൾ അനന്തമായി വീണ്ടും വ്യവഹാരം ചെയ്യുന്നത് ഇത് തടയുന്നു.',
  'sub-judice': 'ഇപ്പോൾ ഒരു കോടതിയിൽ നിലവിലിരിക്കുന്നതും ഇതുവരെ തീരുമാനിച്ചിട്ടില്ലാത്തതുമായ ഒരു വിഷയം. ഒരു സബ് ജുഡീസ് വിഷയത്തിൽ പരസ്യമായി അഭിപ്രായം പറയുന്നതോ മുൻവിധി പറയുന്നതോ ചിലപ്പോൾ കോടതിയലക്ഷ്യമായി കണക്കാക്കാം.',
  'ultra-vires': 'ഒരു വ്യക്തിയുടെയോ സ്ഥാപനത്തിന്റെയോ നിയമപരമായ അധികാരത്തിനോ അധികാരപരിധിക്കോ അപ്പുറം ചെയ്ത ഒരു പ്രവൃത്തി, ഉദാഹരണത്തിന് മെമ്മോറാണ്ടം ഓഫ് അസോസിയേഷനിൽ പ്രസ്താവിച്ച ലക്ഷ്യങ്ങൾക്ക് പുറത്ത് പ്രവർത്തിക്കുന്ന ഒരു കമ്പനി, അല്ലെങ്കിൽ നിയമം നൽകിയ അധികാരങ്ങൾ കവിയുന്ന ഒരു സർക്കാർ അധികാരി. ഒരു അൾട്രാ വൈറസ് പ്രവൃത്തി സാധാരണയായി അസാധുവായി കണക്കാക്കുന്നു.',
  'mens-rea': 'ഒരു പ്രവൃത്തി ഒരു കുറ്റകൃത്യമായി കണക്കാക്കാൻ, ഉദ്ദേശമോ അറിവോ പോലുള്ള, അത് ചെയ്യുമ്പോൾ ഒരു വ്യക്തിക്ക് സാധാരണയായി ഉണ്ടായിരിക്കേണ്ട കുറ്റകരമായ മാനസികാവസ്ഥ. മിക്ക ക്രിമിനൽ കുറ്റകൃത്യങ്ങൾക്കും, കുറ്റകരമായ പ്രവൃത്തിയും ഈ കുറ്റകരമായ മനസ്സും രണ്ടും പ്രോസിക്യൂഷൻ തെളിയിക്കേണ്ടതുണ്ട്.',
  'actus-reus': 'ഒരു കുറ്റകൃത്യത്തിന്റെ അടിസ്ഥാനമായ ശാരീരിക പ്രവൃത്തിയോ പെരുമാറ്റമോ, അതിന് പിന്നിലുള്ള മാനസികാവസ്ഥയായ മെൻസ് റിയയിൽ നിന്ന് വ്യത്യസ്തമായി. മിക്ക കുറ്റകൃത്യങ്ങൾക്കും, കുറ്റാരോപിതൻ യഥാർത്ഥത്തിൽ ഈ കുറ്റകരമായ പ്രവൃത്തി ചെയ്തെന്ന് പ്രോസിക്യൂഷൻ തെളിയിക്കേണ്ടതുണ്ട്.',
  'audi-alteram-partem': 'ആരെയും കേൾക്കാനുള്ള ന്യായമായ അവസരവും സ്വന്തം ഭാഗം അവതരിപ്പിക്കാനുള്ള അവസരവും നൽകാതെ വിധിക്കരുതെന്നോ ശിക്ഷിക്കരുതെന്നോ ഉള്ള തത്വം. കോടതികളും ട്രിബ്യൂണലുകളും പിന്തുടരുന്ന നാച്ചുറൽ ജസ്റ്റിസിന്റെ അടിസ്ഥാന നിയമങ്ങളിൽ ഒന്നാണ് ഇത്.',
  'caveat-emptor': 'വാങ്ങുന്നയാൾ, വാങ്ങൽ പൂർത്തിയാക്കുന്നതിന് മുൻപ്, വാങ്ങുന്ന വസ്തുവിന്റെ ഗുണനിലവാരവും സ്ഥിതിയും പരിശോധിക്കേണ്ടത് തങ്ങളുടെ ഉത്തരവാദിത്തമാണ് എന്ന തത്വം. വിൽപ്പനക്കാർക്ക് കൂടി ബാധ്യതകൾ നൽകുന്ന ഉപഭോക്തൃ സംരക്ഷണ നിയമം, ഇന്ത്യയിൽ ഇതിന്റെ പ്രയോഗം ഗണ്യമായി ചുരുക്കിയിട്ടുണ്ട്.',
  'bona-fide': 'സത്യസന്ധമായി, നല്ല വിശ്വാസത്തോടെ, വഞ്ചിക്കാനുള്ള ഒരു ഉദ്ദേശവുമില്ലാതെ ചെയ്തത്. തർക്കങ്ങൾ തീരുമാനിക്കുമ്പോൾ, പ്രത്യേകിച്ച് സത്യസന്ധതയോ യഥാർത്ഥ വിശ്വാസമോ ഫലത്തെ ബാധിക്കുന്നിടത്ത്, ഒരു കക്ഷിയുടെ പെരുമാറ്റം ബോണ ഫൈഡ് ആയിരുന്നോ എന്ന് കോടതികൾ പലപ്പോഴും നോക്കുന്നു.',
  'mala-fide': 'ബോണ ഫൈഡ് പെരുമാറ്റത്തിന് വിപരീതമായി, മോശം വിശ്വാസത്തോടെ, സത്യസന്ധമല്ലാത്തതോ അനുചിതമായതോ ആയ ഉദ്ദേശത്തോടെ ചെയ്തത്. ഒരു വ്യക്തിപരമായ വൈരാഗ്യം തീർക്കാൻ എടുത്ത ഒരു ഔദ്യോഗിക തീരുമാനം പോലുള്ള, മല ഫൈഡ് ആയി എടുത്ത ഒരു നടപടി, അത് സാങ്കേതികമായി ആ വ്യക്തിയുടെ അധികാരത്തിനകത്തായിരുന്നെങ്കിലും, കോടതിക്ക് റദ്ദാക്കാം.',
  'prima-facie': 'മേൽക്കാഴ്ചയിൽ, അല്ലെങ്കിൽ വിഷയം പൂർണ്ണമായി വിശദമായി പരിശോധിക്കുന്നതിന് മുൻപ്, ലഭ്യമായ വിവരത്തിന്റെ ആദ്യ നോട്ടത്തിന്റെ അടിസ്ഥാനത്തിൽ. നോട്ടീസ് നൽകുകയോ ഒരു ഇടക്കാല ഉത്തരവ് നൽകുകയോ പോലുള്ള ചില നടപടികൾ സ്വീകരിക്കുന്നതിന് മുൻപ്, ഒരു പ്രൈമ ഫേസി കേസ് നിലവിലുണ്ടെന്ന് കോടതിക്ക് പലപ്പോഴും ബോധ്യപ്പെടേണ്ടതുണ്ട്.',
  'suo-motu': 'ആരും ഔപചാരികമായി ഒരു അപേക്ഷയോ പരാതിയോ നൽകാതെ, ഒരു കോടതിയോ അധികാരിയോ സ്വന്തം മുൻകൈയിൽ സ്വീകരിക്കുന്ന നടപടി.',
  'obiter-dicta': 'ഒരു വിധിയിൽ ജഡ്ജ് നടത്തുന്ന, കേസ് തീരുമാനിക്കാൻ അനിവാര്യമല്ലാത്ത പരാമർശങ്ങളോ നിരീക്ഷണങ്ങളോ, തീരുമാനത്തിന്റെ ബന്ധനമായ ഭാഗം രൂപപ്പെടുത്തുന്ന യഥാർത്ഥ ന്യായവാദമായ റേഷ്യോ ഡിസിഡെൻഡിയിൽ നിന്ന് വ്യത്യസ്തമായി. പിന്നീടുള്ള കേസുകളിൽ ഒബിറ്റർ ഡിക്റ്റ പ്രേരണാത്മകമായിരിക്കാം, പക്ഷേ അത് ബന്ധനമായ മുൻവിധിയായി കണക്കാക്കില്ല.',
  'ratio-decidendi': 'ഒരു കേസിൽ തന്റെ തീരുമാനത്തിലെത്താൻ കോടതി ആശ്രയിക്കുന്ന കേന്ദ്ര നിയമപരമായ ന്യായവാദവും തത്വവും, ആനുഷംഗിക പരാമർശങ്ങളായ ഒബിറ്റർ ഡിക്റ്റയിൽ നിന്ന് വ്യത്യസ്തമായി. ഈ ന്യായവാദമാണ്, വിധിയിലെ ഓരോ പ്രസ്താവനയുമല്ല, പിന്നീടുള്ള കേസുകൾക്ക് ബന്ധനമായ മുൻവിധി രൂപപ്പെടുത്തുന്നത്.',
  'ab-initio': 'തുടക്കം മുതൽ തന്നെ. ഒരു കരാറോ നിയമനമോ പോലുള്ളത്, ഒരു കോടതി പിന്നീട് അങ്ങനെ പ്രഖ്യാപിച്ച സമയം മുതൽ മാത്രമല്ല, അത് സൃഷ്ടിച്ച നിമിഷം മുതൽ തന്നെ അസാധുവോ ശൂന്യമോ ആയി കണക്കാക്കുന്നതിനെ വിവരിക്കാൻ ഇത് പലപ്പോഴും ഉപയോഗിക്കുന്നു.',
  'in-personam': 'ഒരു പ്രത്യേക വ്യക്തിക്കെതിരെ നിർദ്ദേശിക്കുന്ന, ആ വ്യക്തിക്ക് മാത്രം ബന്ധനമായ, ലോകം മൊത്തത്തിനെതിരെ നിർദ്ദേശിക്കുന്ന റൈറ്റ് ഇൻ റെമിന് വിപരീതമായ, ഒരു അവകാശം അല്ലെങ്കിൽ കോടതി ഉത്തരവ്.',
  'in-rem': 'ഒരു സ്വത്തോ നിലയോ പോലുള്ള ഒരു വസ്തുവിനെ സംബന്ധിച്ച്, ഒരു പ്രത്യേക വ്യക്തിക്ക് മാത്രം ബന്ധനമായ റൈറ്റ് ഇൻ പെർസണത്തിന് വിപരീതമായി, ലോകം മൊത്തത്തിന് ബന്ധനമായ ഒരു അവകാശം അല്ലെങ്കിൽ കോടതി ഉത്തരവ്.',
  'per-incuriam': 'ശ്രദ്ധയില്ലാത്തതിന് കാരണമായി, സാധാരണയായി ഒരു ബന്ധനമായ മുൻവിധിയോ ബന്ധപ്പെട്ട സ്റ്റാറ്റ്യൂട്ടറി വ്യവസ്ഥയോ പ്രയോഗിക്കേണ്ടത് കോടതി അവഗണിച്ചതിന് കൊടുക്കുന്ന ഒരു തീരുമാനം. പെർ ഇൻക്യൂറിയം ആയി കണ്ടെത്തിയ ഒരു വിധി ആ പോയിന്റിൽ ബന്ധനമായ മുൻവിധിയായി കണക്കാക്കില്ല.',
  'stare-decisis': 'ഓരോ സമാന കേസും പുതുതായി തീരുമാനിക്കുന്നതിന് പകരം, കോടതികൾ മുൻ തീരുമാനങ്ങൾ നിശ്ചയിച്ച മുൻവിധികൾ, പ്രത്യേകിച്ച് ഉയർന്ന കോടതികളുടേത്, പിന്തുടരണമെന്ന തത്വം. നിയമം പ്രയോഗിക്കുന്ന രീതിയിൽ സ്ഥിരതയും പ്രവചനക്ഷമതയും ഇത് പ്രോത്സാഹിപ്പിക്കുന്നു.',
  'habeas-corpus': 'ഭരണഘടനയുടെ ആർട്ടിക്കിൾ 32 അല്ലെങ്കിൽ ആർട്ടിക്കിൾ 226 പ്രകാരം നൽകുന്ന ഒരു റിട്ട്, ഒരു വ്യക്തിയെ കസ്റ്റഡിയിൽ വച്ചിരിക്കുന്ന ഒരു വ്യക്തിയെയോ അധികാരിയെയോ, ആ വ്യക്തിയെ കോടതിയിൽ ഹാജരാക്കാനും തടങ്കൽ ന്യായീകരിക്കാനും നിർദ്ദേശിക്കുന്നത്. നിയമവിരുദ്ധമോ ഇഷ്ടാനുസൃതമോ ആയ തടങ്കലിനെതിരായ പ്രധാന പരിഹാരമാണ് ഇത്.',
  'mandamus': 'ഭരണഘടനയുടെ ആർട്ടിക്കിൾ 32 അല്ലെങ്കിൽ ആർട്ടിക്കിൾ 226 പ്രകാരം നൽകുന്ന ഒരു റിട്ട്, ഒരു പൊതു അധികാരിയോ ഉദ്യോഗസ്ഥനോ ചെയ്യാൻ പരാജയപ്പെട്ടതോ വിസമ്മതിച്ചതോ ആയ ഒരു പൊതു കടമ നിർവ്വഹിക്കാൻ നിർദ്ദേശിക്കുന്നത്.',
  'certiorari': 'ഭരണഘടനയുടെ ആർട്ടിക്കിൾ 32 അല്ലെങ്കിൽ ആർട്ടിക്കിൾ 226 പ്രകാരം നൽകുന്ന ഒരു റിട്ട്, അതിലൂടെ ഒരു ഉയർന്ന കോടതി ഒരു ലോവർ കോടതിയിൽ നിന്നോ ട്രിബ്യൂണലിൽ നിന്നോ ഒരു കേസിന്റെ റെക്കോർഡ് വിളിപ്പിക്കുകയും, അത് അധികാരപരിധി ഇല്ലാതെയോ നാച്ചുറൽ ജസ്റ്റിസ് ലംഘിച്ചോ നൽകിയതാണെങ്കിൽ അതിന്റെ ഉത്തരവ് റദ്ദാക്കുകയും ചെയ്യുന്നത്.',
  'quo-warranto': 'ഭരണഘടനയുടെ ആർട്ടിക്കിൾ 32 അല്ലെങ്കിൽ ആർട്ടിക്കിൾ 226 പ്രകാരം നൽകുന്ന ഒരു റിട്ട്, ഒരു വ്യക്തി ഒരു പൊതു ഓഫീസ് കൈവശം വയ്ക്കുന്ന അധികാരത്തെ ചോദ്യം ചെയ്ത്, നിയമപരമായ അവകാശമില്ലാതെ അത് കൈവശം വയ്ക്കുന്നതായി കണ്ടെത്തിയാൽ അവരെ അതിൽ നിന്ന് നീക്കം ചെയ്യുന്നത്.',
  'amicus-curiae': 'ഒരു കേസിൽ കക്ഷിയല്ലാത്ത ഒരു വ്യക്തിയോ സ്ഥാപനമോ, കേസുമായി ബന്ധപ്പെട്ട വിവരമോ വൈദഗ്ധ്യമോ വാദങ്ങളോ നൽകി കോടതിയെ സഹായിക്കാൻ അനുവാദം നൽകുന്നത്, സാധാരണയായി പൊതു പ്രാധാന്യമുള്ള ഒരു വിഷയത്തിൽ.',
  'de-facto': 'ഇത് ഔപചാരികമായോ നിയമപരമായോ അംഗീകരിച്ചതാണോ എന്നത് പരിഗണിക്കാതെ, പ്രായോഗികമായോ വസ്തുതയിലോ നിലവിലുള്ളത്. "നിയമപ്രകാരം" നിലവിലുള്ളത് എന്നർത്ഥമുള്ള "ഡി ജൂറെ" യുമായി പലപ്പോഴും താരതമ്യം ചെയ്യുന്നു.',
  'de-jure': 'ഇത് പ്രയോഗത്തിൽ യഥാർത്ഥത്തിൽ സംഭവിക്കുന്നതിനെ പ്രതിഫലിപ്പിക്കുന്നോ ഇല്ലയോ എന്നത് പരിഗണിക്കാതെ, നിയമപ്രകാരം അല്ലെങ്കിൽ ഒരു നിയമപരമായ അവകാശമായി നിലവിലുള്ളത്. "വസ്തുതയിൽ" നിലവിലുള്ളത് എന്നർത്ഥമുള്ള "ഡി ഫാക്ടോ" യുമായി പലപ്പോഴും താരതമ്യം ചെയ്യുന്നു.',
  'inter-alia': 'മറ്റ് കാര്യങ്ങൾക്കിടയിൽ. ഒരു ലിസ്റ്റോ പ്രസ്താവനയോ പൂർണ്ണമല്ലെന്ന് സൂചിപ്പിക്കാൻ ഉപയോഗിക്കുന്നത് — പ്രത്യേകമായി പരാമർശിച്ചതിന് പുറമെ മറ്റ് കാര്യങ്ങളും നിലവിലുണ്ട് എന്നതിന്.',
  'ipso-facto': 'ആ വസ്തുത തന്നെ കൊണ്ട്, വേറെ ഒന്നും ആവശ്യമില്ലാതെ ഒരു പ്രത്യേക ഫലമോ അനന്തരഫലമോ ഉണ്ടാക്കാൻ.',
  'quid-pro-quo': 'താരതമ്യ മൂല്യമുള്ള മറ്റൊന്നിന് പകരമായി നൽകുന്നതോ ചെയ്യുന്നതോ ആയ ഒന്ന്. ഉദാഹരണത്തിന്, കരാർ നിയമത്തിൽ, ഒരു കരാറിലെ കക്ഷികൾക്കിടയിൽ കൈമാറുന്ന കൺസിഡറേഷൻ വിവരിക്കാൻ ഉപയോഗിക്കുന്നു.',
  'status-quo': 'ഒരു നിശ്ചിത സമയത്തെ നിലവിലുള്ള അവസ്ഥ. കേസ് നിലവിലിരിക്കുമ്പോൾ നിലവിലെ സ്ഥിതി മാറ്റുന്നതിൽ നിന്ന് ഏതൊരു കക്ഷിയെയും തടയാൻ, കോടതികൾ പലപ്പോഴും "സ്റ്റാറ്റസ് ക്വോ നിലനിർത്താൻ" ഇടക്കാല ഉത്തരവുകൾ നൽകുന്നു.',
  'pari-passu': 'തുല്യ നിലയിൽ, മുൻഗണനയില്ലാതെ. പ്രധാനമായും കടക്കാർക്കോ ക്ലെയിംകാർക്കോ, ആരും മറ്റൊരാളെക്കാൾ മുൻഗണന നൽകാതെ, ആനുപാതികമായി പണം നൽകുകയോ പെരുമാറുകയോ ചെയ്യുന്നിടത്ത് ഉപയോഗിക്കുന്നു.',
  'res-ipsa-loquitur': 'വസ്തു തന്നെ സംസാരിക്കുന്നു. പ്രധാനമായും അശ്രദ്ധയുടെ കേസുകളിൽ പ്രയോഗിക്കുന്നത്, അവിടെ ഒരു അപകടത്തിന്റെ സാഹചര്യങ്ങൾ അശ്രദ്ധ വ്യക്തമായി സൂചിപ്പിക്കുന്നതിനാൽ, അത് കൃത്യമായി എങ്ങനെ സംഭവിച്ചു എന്നതിന് കൂടുതൽ തെളിവ് ആവശ്യമില്ലാതെ, ആ വസ്തുതകൾ തന്നെ അശ്രദ്ധയുടെ തെളിവായി കണക്കാക്കുന്നു.',
  'ejusdem-generis': 'നിയമ വ്യാഖ്യാനത്തിന്റെ ഒരു നിയമം: ഒരു നിയമം പ്രത്യേക ഇനങ്ങൾ പട്ടികപ്പെടുത്തി പിന്നാലെ പൊതുവായ വാക്കുകൾ ഉപയോഗിക്കുന്നിടത്ത്, ആ പൊതു വാക്കുകൾ, എന്തുമാകട്ടെ ഉൾക്കൊള്ളുന്നതായിട്ടല്ല, പട്ടികപ്പെടുത്തിയ ഇനങ്ങളുടെ അതേ തരത്തിലുള്ള കാര്യങ്ങളിലേക്ക് പരിമിതപ്പെടുത്തി വായിക്കുന്നു.',
  'noscitur-a-sociis': 'നിയമ വ്യാഖ്യാനത്തിന്റെ ഒരു നിയമം: ഒരു നിയമത്തിലെ അവ്യക്തമായ ഒരു വാക്കിന്റെയോ ശൈലിയുടെയോ അർത്ഥം, അതിന് ചുറ്റുമുള്ള വാക്കുകൾ നോക്കിയാൽ മനസ്സിലാക്കാം, കാരണം ഒരു വാക്ക് അതിന് ഒപ്പമുള്ള കൂട്ടുകെട്ടിലൂടെ തിരിച്ചറിയപ്പെടുന്നു.',
  'doli-incapax': 'ഒരു കുറ്റകൃത്യം ചെയ്യാൻ കഴിവില്ലാത്തത്. പ്രധാനമായും ചെറിയ കുട്ടികൾക്ക് ഉപയോഗിക്കുന്നത്, ഒരു നിശ്ചിത പ്രായത്തിന് താഴെ, സ്വന്തം പ്രവർത്തനങ്ങൾക്ക് ക്രിമിനൽ ഉത്തരവാദിത്തം വഹിക്കാൻ ആവശ്യമായ ഗ്രാഹ്യം ഇല്ലെന്ന് നിയമം അനുമാനിക്കുന്നവർ.',
  'uberrima-fides': 'പരമമായ നല്ല വിശ്വാസം. ചില കരാറുകൾ, ഏറ്റവും പ്രധാനമായി ഇൻഷുറൻസ് കരാറുകൾ, മിക്ക കരാറുകൾക്കും ബാധകമായ, തെറ്റായി അവതരിപ്പിക്കരുതെന്ന സാധാരണ കടമയ്ക്കും അപ്പുറം പോയി, എല്ലാ പ്രധാന വസ്തുതകളും സ്വമേധയാ മറുകക്ഷിയോട് വെളിപ്പെടുത്താൻ ഓരോ കക്ഷിയെയും ആവശ്യപ്പെടുന്നു.',
  'de-novo': 'പുതുതായി, അല്ലെങ്കിൽ പുതുതായി ആരംഭിച്ച്. ഒരു "ഡി നോവോ" ഹിയറിംഗോ വിചാരണയോ എന്നാൽ, വെറും പിഴവുകൾക്കായി അവലോകനം ചെയ്യുന്നതിന് പകരം, മുൻ നടപടി നടന്നിട്ടില്ലെന്ന മട്ടിൽ, വിഷയം ആദ്യം മുതൽ വീണ്ടും കേൾക്കുന്നു എന്നാണ്.',
  'functus-officio': 'തന്റെ കടമയോ അധികാരമോ നിർവ്വഹിച്ചുകഴിഞ്ഞ്, അതിനാൽ ആ വിഷയത്തിൽ കൂടുതൽ പ്രവർത്തിക്കാനുള്ള അധികാരം ഇല്ലാതായത്. ഉദാഹരണത്തിന്, ഒരു അന്തിമ ഡിക്രി ഇതിനകം നൽകിയ കോടതി, ആ കേസുമായി ബന്ധപ്പെട്ട മിക്ക കാര്യങ്ങളിലും ഫങ്ക്ടസ് ഒഫീഷ്യോ ആണ്.',
  'sui-generis': 'തനതായത്, അല്ലെങ്കിൽ അദ്വിതീയം — നിലവിലുള്ള ഒരു വിഭാഗത്തിലോ വർഗ്ഗീകരണത്തിലോ ശരിയായി ഇണങ്ങാത്തത്, അതിനാൽ അതിന്റേതായ വേറിട്ട നിയമപരമായ പരിഗണന ആവശ്യമായത്.',
  'lis-pendens': 'നിലവിലുള്ള ഒരു സ്യൂട്ടോ വ്യവഹാരമോ. ലിസ് പെൻഡൻസ് തത്വപ്രകാരം, ഒരു നടന്നുകൊണ്ടിരിക്കുന്ന കേസിന്റെ വിഷയമായ ഒരു സ്വത്ത്, ആ കേസിലെ മറുകക്ഷിയുടെ അവകാശങ്ങളെ ബാധിക്കുന്ന വിധത്തിൽ കൈമാറ്റം ചെയ്യാനാവില്ല.',
  'pendente-lite': 'വ്യവഹാരം നിലവിലിരിക്കുമ്പോൾ. ഇടക്കാല മെയിന്റനൻസോ കസ്റ്റഡിയോ പോലുള്ള, കേസ് അന്തിമമായി തീർപ്പാക്കുന്നതുവരെ മാത്രം, കേസിന്റെ കാലയളവിലേക്ക് മാത്രം ബാധകമായ ഒരു ഉത്തരവ്, അവകാശം, അല്ലെങ്കിൽ ക്രമീകരണം വിവരിക്കാൻ ഉപയോഗിക്കുന്നു.',
  'ex-post-facto': 'സംഭവത്തിന് ശേഷം. ഒരു നിയമം ഉണ്ടാക്കിയ തീയതിക്ക് മുൻപ് മുതൽ പ്രാബല്യത്തോടെ, ഒരു പ്രവൃത്തി ക്രിമിനൽ കുറ്റമാക്കാനോ അതിനുള്ള ശിക്ഷ വർദ്ധിപ്പിക്കാനോ ശ്രമിക്കുന്ന ഒരു നിയമത്തിന്, ഏറ്റവും സാധാരണയായി ഉപയോഗിക്കുന്നത് — ക്രിമിനൽ കാര്യങ്ങളിൽ ഭരണഘടന സാധാരണയായി നിരോധിക്കുന്ന ഒന്ന്.',
  'nunc-pro-tunc': 'ഇപ്പോൾ അന്നത്തേക്ക്. ഒരു കോടതി ഇപ്പോൾ നൽകുന്ന, പക്ഷേ ഒരു മുൻകാല തീയതി മുതൽ നിയമപരമായി പ്രാബല്യത്തിൽ വരുന്ന ഒരു ഉത്തരവ്, ഒരു വൈകലോ ഒഴിവോ ഇല്ലെങ്കിൽ ഒരു കക്ഷിയുടെ അവകാശങ്ങളെ അന്യായമായി ബാധിക്കുന്നിടത്ത്, സാധാരണയായി റെക്കോർഡ് തിരുത്താൻ ഉപയോഗിക്കുന്നത്.',
  'quantum-meruit': 'ഒരാൾ സമ്പാദിച്ച അത്രയും. ഒരു നിശ്ചിത വില സമ്മതിക്കാതിരുന്നപ്പോളോ, ഒരു കരാർ പൂർത്തിയാക്കാൻ കഴിയാതിരുന്നപ്പോളോ, നഷ്ടപരിഹാരത്തിനുള്ള ഒരു ക്ലെയിമിന് പകരം, ചെയ്ത ജോലിക്കോ നൽകിയ സേവനങ്ങൾക്കോ ന്യായമായ പേയ്‌മെന്റിനുള്ള ഒരു ക്ലെയിം.',
  'bona-vacantia': 'ഉടമയില്ലാത്ത സ്വത്ത്. തിരിച്ചറിയാവുന്ന ഒരു ഉടമയുമില്ലാത്ത സ്വത്ത്, ഉദാഹരണത്തിന് പിരിച്ചുവിട്ട ഒരു കമ്പനിയുടെയോ അനന്തരാവകാശികളോ വിൽ ഇല്ലാതെ മരിച്ച ഒരു വ്യക്തിയുടെയോ ആസ്തികൾ, നിയമപ്രകാരം സർക്കാരിലേക്ക് പോകുന്നത്.',
  'modus-operandi': 'ഒരു പ്രത്യേക പ്രവർത്തന രീതിയോ മാതൃകയോ. ക്രിമിനൽ കാര്യങ്ങളിൽ, ഒരു കുറ്റകൃത്യം നടത്തുന്ന സ്വഭാവികമായ രീതിയെ ഇത് പരാമർശിക്കുന്നു, ഇത് ചിലപ്പോൾ സമാനമായ മുൻകാല കുറ്റകൃത്യങ്ങളുമായി ഒരു കുറ്റാരോപിതനെ ബന്ധിപ്പിക്കാൻ സഹായിക്കും.',
  'coram-non-judice': 'ജഡ്ജ് അല്ലാത്ത ഒരാളുടെ മുന്നിൽ, അല്ലെങ്കിൽ വിഷയം കേൾക്കാൻ അധികാരമില്ലാത്ത ഒരു കോടതിയുടെ മുന്നിൽ. കോറം നോൺ ജുഡീസ് ആയി നൽകിയ ഒരു ഉത്തരവ്, തുടക്കം മുതൽ തന്നെ ശരിയായ അധികാരപരിധി ഇല്ലാതെ നൽകിയതിനാൽ, ശൂന്യമായി കണക്കാക്കുന്നു.',
  'mutatis-mutandis': 'ആവശ്യമായ മാറ്റങ്ങൾ വരുത്തിക്കൊണ്ട്. ഒരു സാഹചര്യത്തിനായി എഴുതിയ ഒരു നിയമം, വ്യവസ്ഥ, അല്ലെങ്കിൽ ക്ലോസ്, സമാനമായ മറ്റൊരു സാഹചര്യത്തിൽ പ്രയോഗിക്കുമ്പോൾ, അനിവാര്യമായി വ്യത്യാസപ്പെടേണ്ട വിശദാംശങ്ങൾ മാത്രം മാറ്റിക്കൊണ്ട് ഉപയോഗിക്കുന്നു.',
  'sine-die': 'തുടരാനുള്ള നിശ്ചിത തീയതിയില്ലാതെ. "സൈൻ ഡൈ" മാറ്റിവച്ച ഒരു ഹിയറിംഗോ വിഷയമോ, അടുത്തത് എപ്പോൾ എടുക്കും എന്നതിന് ഒരു പ്രത്യേക തീയതിയും നിശ്ചയിക്കാതെ, അനിശ്ചിതമായി നീട്ടിവച്ചിരിക്കുന്നു.',
  'sine-qua-non': 'ഒന്ന് സംഭവിക്കാനോ നിലനിൽക്കാനോ ഒഴിച്ചുകൂടാനാവാത്ത ഒരു അനിവാര്യ നിബന്ധന. ഒരു പ്രത്യേക ഫലത്തിന് തീർത്തും ഒഴിച്ചുകൂടാനാവാത്ത ഒരു ആവശ്യകതയെ വിവരിക്കാൻ ഉപയോഗിക്കുന്നു.',
  'nemo-judex-in-causa-sua': 'ആരും സ്വന്തം കേസിൽ ജഡ്ജ് ആകരുത്. ഒരു വിഷയം തീരുമാനിക്കുന്ന വ്യക്തിക്കോ അധികാരിക്കോ അതിന്റെ ഫലത്തിൽ വ്യക്തിപരമായ താൽപ്പര്യം ഉണ്ടാകരുതെന്ന് ആവശ്യപ്പെടുന്ന നാച്ചുറൽ ജസ്റ്റിസിന്റെ ഒരു അടിസ്ഥാന തത്വം.',
  'volenti-non-fit-injuria': 'സന്നദ്ധനായ ഒരാൾക്ക് ഒരു ദോഷവും സംഭവിക്കുന്നില്ല. പ്രധാനമായും ടോർട്ട് നിയമത്തിൽ ഉപയോഗിക്കുന്ന ഒരു പ്രതിവാദം, അറിഞ്ഞും സ്വമേധയാ ഒരു ദോഷത്തിന്റെ അപകടസാധ്യത സ്വീകരിച്ച ഒരു വ്യക്തിക്ക് പിന്നീട് ആ ദോഷത്തിന് നഷ്ടപരിഹാരം ക്ലെയിം ചെയ്യാനാവില്ലെന്നത്.',
};
